export type GlossaryTerm = {
  id: string;
  name: string;
  aliases?: string[];
  description: string;
  formula?: string;
  example?: string;
  caution?: string;
};

export const glossaryTerms: GlossaryTerm[] = [
  { id: "acao", name: "Ação", aliases: ["Ações"], description: "Uma pequena parte da propriedade de uma empresa. Quem compra ações torna-se acionista, ou seja, um dos seus donos. Pode ganhar com a valorização das ações e com a distribuição de lucros, mas também pode perder dinheiro se o preço cair.", example: "100 ações compradas a R$ 20 custam R$ 2.000, antes de taxas. Se o preço cair para R$ 18, essas mesmas ações passam a valer R$ 1.800." },
  { id: "amortizacao", name: "Amortização", description: "É a parte do pagamento usada para devolver o dinheiro que foi emprestado e reduzir o valor que ainda falta devolver. Não é a mesma coisa que juros, que são o custo de usar esse dinheiro. Uma parcela de empréstimo pode incluir amortização, juros e tarifas; por isso, nem todo o valor pago reduz a dívida.", example: "Você ainda precisa devolver R$ 10.000 de um empréstimo e paga uma parcela de R$ 700: R$ 500 para reduzir a dívida e R$ 200 de juros. A amortização é de R$ 500, e o valor emprestado que falta devolver cai para R$ 9.500. Os R$ 200 de juros não reduzem esse valor. O exemplo não inclui tarifas nem novos empréstimos." },
  { id: "aporte", name: "Aporte", description: "Dinheiro que você coloca em um investimento, seja ao começar, todos os meses ou de vez em quando. Não inclui os ganhos que o próprio investimento produz.", example: "R$ 5.000 no início mais 12 depósitos de R$ 500 somam R$ 11.000 colocados por você. Os juros recebidos são ganhos, não novos aportes." },
  { id: "acao-preferencial", name: "Ação preferencial", aliases: ["PN"], description: "Tipo de ação com preferências previstas no estatuto da empresa, como prioridade em dividendos ou na devolução do capital se ela for encerrada. Pode ter voto limitado. Na B3, seus códigos normalmente terminam em 4, 5, 6, 7 ou 8, conforme a classe.", example: "PETR4, ITUB4.", caution: "As preferências variam entre empresas e não garantem pagamento ou ausência de perdas. O direito de voto pode surgir em situações previstas na lei e no estatuto." },
  { id: "acao-ordinaria", name: "Ação ordinária", aliases: ["ON"], description: "Tipo de ação que, em regra, permite votar nas assembleias, reuniões de decisão dos acionistas. Também pode receber dividendos. Na B3, seu código normalmente termina em 3.", example: "BBAS3, VALE3.", caution: "Ter voto não significa controlar a empresa. A influência depende da quantidade de ações e das regras de votação." },
  { id: "benchmark", name: "Benchmark", description: "Referência para avaliar se um investimento teve um resultado maior ou menor que uma comparação escolhida. Pode ser uma taxa, como o CDI, ou um índice, que acompanha um conjunto de investimentos ou de preços.", example: "Se um fundo ganha 11% e sua referência ganha 10% no mesmo período, a diferença é de 1 ponto percentual: 11% menos 10%.", caution: "Compare o mesmo período e confira se taxas e impostos já foram descontados em ambos os resultados. Ganhar mais pode envolver assumir mais risco." },
  { id: "cdb", name: "CDB", aliases: ["Certificado de Depósito Bancário"], description: "Investimento em que você empresta dinheiro a um banco, que se compromete a devolvê-lo com juros. A taxa pode ser definida na contratação, acompanhar uma referência como o CDI ou combinar um índice com uma taxa fixa. O contrato informa quando é possível retirar o dinheiro, chamado de resgate, e a data prevista para devolução, chamada de vencimento.", caution: "Confira se o banco pode cumprir o pagamento, quando você pode sacar, quais impostos incidem e se o investimento atende às regras de garantia do FGC." },
  { id: "cdi", name: "CDI", aliases: ["Taxa DI"], description: "Sigla de Certificado de Depósito Interbancário, usado em empréstimos entre instituições financeiras. Nos investimentos, dizer que algo rende um percentual do CDI normalmente se refere à Taxa DI, calculada a partir dessas operações e usada como referência para os juros.", example: "110% do CDI significa 1,10 vezes a taxa de referência usada no cálculo do produto, e não um ganho de 110% sobre o dinheiro investido.", caution: "A taxa muda ao longo do tempo. Um percentual anual divulgado não garante quanto você ganhará no futuro." },
  { id: "cet", name: "CET", aliases: ["Custo Efetivo Total"], description: "Taxa que reúne juros, tarifas, impostos e outros custos de um empréstimo ou financiamento. Ajuda a identificar a dívida mais cara, além da taxa de juros anunciada.", example: "Duas propostas com o mesmo valor recebido e prazo têm CET anual de 20% e 25%. A de 25% tem maior custo efetivo, mesmo que anuncie juros menores.", caution: "Compare taxas na mesma unidade de tempo e condições equivalentes. CET menor não significa necessariamente menor valor total pago se os prazos forem diferentes." },
  { id: "cota", name: "Cota", description: "Cada uma das partes em que a participação em um fundo é dividida. Ao comprar cotas, você participa dos resultados do fundo. Em bolsa, o preço pago por uma cota pode ser diferente da parcela dos bens e investimentos do fundo, descontadas suas dívidas, que ela representa nos registros contábeis.", example: "20 cotas compradas a R$ 100 custam R$ 2.000, antes de taxas. Se a cotação mudar, o valor dessas cotas também muda." },
  { id: "cra", name: "CRA", aliases: ["Certificado de Recebíveis do Agronegócio"], description: "Investimento ligado a valores que empresas do agronegócio têm a receber, chamados de recebíveis. Uma securitizadora, empresa que organiza esses direitos de pagamento em títulos para investidores, emite o CRA. Os pagamentos dependem dos contratos e da estrutura da operação.", example: "Uma operação pode reunir valores que uma empresa do setor tem a receber pela venda de produtos agrícolas. Esses recebíveis podem servir de base para um CRA, conforme as regras da emissão.", caution: "Não tem garantia do FGC. Confira quem deve pagar, as garantias, as datas de pagamento e a possibilidade de vender antes do vencimento. Atrasos ou falta de pagamento podem causar perdas." },
  { id: "cri", name: "CRI", aliases: ["Certificado de Recebíveis Imobiliários"], description: "Investimento ligado a valores que serão recebidos em operações imobiliárias, chamados de recebíveis, como pagamentos de financiamentos ou aluguéis. É emitido por uma securitizadora, empresa que organiza esses direitos de pagamento em títulos para investidores. Não é o mesmo que comprar um imóvel nem uma LCI de um banco.", example: "Pagamentos futuros de financiamentos imobiliários podem servir de base para um CRI. A operação transforma esses valores a receber em um título, cujos pagamentos seguem as condições da emissão.", caution: "Não tem garantia do FGC. Confira quem deve pagar, as garantias, as datas de pagamento e a possibilidade de vender antes do vencimento. Atrasos ou falta de pagamento podem causar perdas." },
  { id: "dividend-yield", name: "Dividend yield", aliases: ["DY"], description: "Percentual que compara os valores distribuídos por ação ou cota, chamados de proventos, com o preço dessa ação ou cota. Ajuda a entender quanto foi distribuído em um período em relação ao preço usado na comparação. Não inclui o ganho ou a perda com a mudança desse preço.", formula: "DY = valor distribuído por ação ou cota no período ÷ preço da ação ou cota × 100", example: "Uma ação que distribuiu R$ 6 em 12 meses, comparada a um preço de R$ 100, tem DY de 6%: 6 ÷ 100 × 100.", caution: "Um pagamento fora do comum ou uma queda do preço pode elevar o DY sem indicar melhora do negócio. Distribuições futuras não são garantidas." },
  { id: "dividendos", name: "Dividendos", description: "Parte do lucro de uma empresa paga aos seus acionistas, proporcionalmente às ações e aos direitos de cada tipo de ação. A empresa pode distribuir valores diferentes ou não distribuir, conforme seus resultados e as regras aplicáveis.", example: "Se uma empresa paga R$ 0,50 por ação e você possui 100 ações com direito ao pagamento, recebe R$ 50.", caution: "Na data ex, quando novas compras deixam de dar direito àquele pagamento, o preço de referência da ação é ajustado pela distribuição. Portanto, o dividendo não é um ganho extra sem efeito no valor da ação. FIIs distribuem rendimentos, não dividendos de empresas." },
  { id: "divida-liquida-ebitda", name: "Dívida líquida / EBITDA", description: "Compara as dívidas de empréstimos e financiamentos, descontado o dinheiro disponível em caixa e aplicações de acesso imediato, com o EBITDA, uma medida do resultado da atividade da empresa antes de certos custos. Ajuda a avaliar o tamanho da dívida em relação a esse resultado, geralmente de 12 meses.", formula: "Dívida líquida / EBITDA = (dívidas de empréstimos e financiamentos − dinheiro em caixa e aplicações de acesso imediato) ÷ EBITDA", example: "Uma empresa deve R$ 400 milhões e tem R$ 100 milhões disponíveis: sua dívida líquida é R$ 300 milhões. Com EBITDA de R$ 100 milhões no ano, o indicador é 3 vezes.", caution: "Isso não significa que a dívida será paga em três anos: o EBITDA não é todo dinheiro livre para pagar dívidas. Se ele for negativo ou quase zero, a comparação perde utilidade. Bancos exigem outros indicadores." },
  { id: "ebitda", name: "EBITDA", aliases: ["LAJIDA"], description: "Medida do resultado da atividade de uma empresa antes de descontar juros, impostos sobre o lucro, depreciação e amortização. Aqui, depreciação e amortização são registros contábeis que distribuem o custo de bens, softwares e outros direitos ao longo do tempo; não são o pagamento de uma dívida. O EBITDA ajuda a comparar negócios, mas não mostra quanto dinheiro está livre na conta.", caution: "Pode não considerar gastos importantes, como a compra de equipamentos. Quando divulgado como ajustado, confira quais outros itens foram retirados do cálculo." },
  { id: "etf", name: "ETF", aliases: ["Fundo de índice", "Exchange Traded Fund"], description: "Fundo com cotas compradas e vendidas em bolsa. Os ETFs de índice buscam acompanhar uma carteira de referência, dando acesso a seus resultados sem comprar cada investimento separadamente.", example: "BOVA11.", caution: "Comprar a cota não coloca cada ativo diretamente em seu nome. Taxas e diferenças na carteira afetam o resultado; acompanhar um índice não elimina perdas." },
  { id: "ev-ebitda", name: "EV / EBITDA", aliases: ["Enterprise value"], description: "Compara o valor da empresa como negócio, chamado de EV, com seu EBITDA, uma medida do resultado da atividade antes de certos custos. Em uma conta simplificada, o EV soma o valor de todas as ações em bolsa às dívidas de empréstimos e financiamentos, descontando o dinheiro disponível em caixa e aplicações de acesso imediato.", formula: "EV / EBITDA = (valor de todas as ações em bolsa + dívida líquida) ÷ EBITDA", example: "EV de R$ 1 bilhão dividido por EBITDA de R$ 200 milhões resulta em 5 vezes: o valor do negócio equivale a cinco vezes esse resultado.", caution: "Esse número não é um prazo de retorno do investimento. As fontes podem fazer ajustes diferentes, e um indicador baixo não prova que a ação está barata." },
  { id: "fgc", name: "FGC", aliases: ["Fundo Garantidor de Créditos", "Fundo Garantidor de Crédito"], description: "Entidade privada sem fins lucrativos que protege determinados depósitos e investimentos em instituições participantes. Pode devolver valores em situações como intervenção ou liquidação, conforme os limites e condições da garantia.", caution: "Nem todo investimento é protegido. Ações, fundos e títulos públicos não recebem essa garantia só por serem comprados em um banco. Confira as regras vigentes no FGC; o pagamento não é necessariamente imediato." },
  { id: "fii", name: "FII", aliases: ["Fundo de Investimento Imobiliário", "Fundos imobiliários"], description: "Fundo que reúne dinheiro de investidores para aplicar no mercado imobiliário, por exemplo em imóveis para aluguel ou em títulos ligados a financiamentos do setor. Você participa por meio de cotas, que são partes do fundo, e pode receber rendimentos conforme os resultados e as regras de distribuição.", example: "HGLG11.", caution: "Não há renda mensal garantida, e o preço das cotas pode cair. Confira quem administra os investimentos, onde o dinheiro está aplicado, as dívidas e a facilidade de vender suas cotas." },
  { id: "ibovespa", name: "Ibovespa", aliases: ["IBOV", "Índice Bovespa"], description: "Principal referência para acompanhar o mercado de ações brasileiro. A B3 calcula o resultado de uma carteira de ações e units escolhidas por critérios de negociação e representatividade. O cálculo considera a variação de preços e os pagamentos aos investidores, como dividendos.", example: "Se o índice passa de 100.000 para 105.000 pontos, ele sobe 5%. Os pontos são uma medida do índice, não o preço em reais de uma ação.", caution: "Não representa todas as empresas da bolsa. A composição muda, e a alta do índice não significa que todas as ações subiram. Para buscar um resultado parecido, existem fundos que o acompanham." },
  { id: "ibrx-100", name: "IBrX 100", aliases: ["IBRX", "Índice Brasil 100"], description: "Índice da B3 que acompanha uma carteira de 100 ações e units selecionadas por critérios de negociação e presença no mercado. O cálculo considera preços e pagamentos aos investidores. É outra referência do mercado brasileiro, com regras de seleção e pesos diferentes dos do Ibovespa.", caution: "São 100 ativos, não necessariamente 100 empresas distintas, pois uma empresa pode ter mais de um tipo de ação. Nenhum deles recebe obrigatoriamente o mesmo peso na carteira." },
  { id: "idiv", name: "IDIV", aliases: ["Índice Dividendos"], description: "Índice da B3 que acompanha ações e units de empresas que se destacam na distribuição de valores aos acionistas, como dividendos e juros sobre capital próprio, outra forma de pagamento ao acionista. A versão de retorno total considera tanto a mudança dos preços quanto esses pagamentos.", caution: "Existe também uma versão que acompanha apenas preços, o IDIV B3 Price Return. Confira qual está sendo usada na comparação. Histórico de distribuições não garante pagamentos futuros." },
  { id: "ifix", name: "IFIX", aliases: ["Índice de Fundos de Investimentos Imobiliários"], description: "Índice da B3 usado como referência para acompanhar fundos imobiliários negociados em bolsa. Reúne cotas de FIIs escolhidas pelas regras do índice. Seu resultado considera a mudança dos preços e os rendimentos distribuídos, tratados no cálculo como reinvestidos.", example: "Se o IFIX sobe 8% em um período, isso não significa que as cotas subiram 8% só no preço: os rendimentos distribuídos também entram no resultado.", caution: "Não inclui todos os FIIs, nem garante renda ou valorização. Compare seu investimento considerando os rendimentos recebidos, e não apenas a mudança do preço da cota." },
  { id: "igp-di", name: "IGP-DI", aliases: ["IGPDI", "Índice Geral de Preços – Disponibilidade Interna"], description: "Indicador de preços calculado pela FGV que combina preços ao produtor, ao consumidor e custos da construção. Tem composição semelhante à do IGP-M, mas usa um período diferente de coleta: do primeiro ao último dia do mês. Pode ser usado em reajustes quando previsto no contrato.", caution: "Não substitua IGP-M por IGP-DI só porque os nomes são parecidos. Os resultados podem ser diferentes; confira o índice e o período indicados no contrato." },
  { id: "igp-m", name: "IGP-M", aliases: ["IGPM", "Índice Geral de Preços – Mercado"], description: "Indicador calculado pela FGV que acompanha preços ao produtor, preços ao consumidor e custos da construção. É conhecido pelo uso em reajustes de aluguel, quando o contrato o prevê. Como inclui preços de etapas diferentes da economia, pode variar de forma bem diferente do IPCA.", example: "Em um reajuste hipotético de 5%, um aluguel de R$ 1.000 passa a R$ 1.050: 1.000 × 1,05. O percentual é fictício; o contrato define o índice e o período usados.", caution: "Nem todo aluguel usa IGP-M. Confira o contrato, o período acumulado e como ele trata uma variação negativa. Não confunda a taxa de um mês com a acumulada em 12 meses." },
  { id: "ima-b", name: "IMA-B", aliases: ["IMAB", "Índice de Mercado ANBIMA B"], description: "Índice da ANBIMA que acompanha uma carteira de títulos públicos ligados ao IPCA, chamados de NTN-B. Considera os preços de negociação desses títulos e seus juros. É uma referência para comparar investimentos em títulos públicos corrigidos pela inflação.", caution: "Não é a própria inflação nem uma taxa de ganho garantida. Pode cair quando os preços dos títulos caem, mesmo que o IPCA esteja subindo. A carteira inclui títulos com diferentes prazos." },
  { id: "incc", name: "INCC", aliases: ["Índice Nacional de Custo da Construção"], description: "Indicador calculado pela FGV que acompanha custos da construção, como materiais, serviços e mão de obra. Pode ser usado para corrigir parcelas de imóveis em construção quando previsto no contrato. Mede custos de construir, não o preço de venda dos imóveis.", caution: "Há versões como INCC-M, INCC-DI e INCC-10, com períodos de coleta diferentes. Confira qual versão e qual período seu contrato usa." },
  { id: "indice", name: "Índice", aliases: ["Índice de mercado", "Índice de preços"], description: "Medida que reúne informações para acompanhar uma mudança ao longo do tempo. Um índice de preços, como o IPCA, acompanha o custo de produtos e serviços. Um índice de mercado, como o Ibovespa, acompanha uma carteira de investimentos selecionados por regras específicas.", caution: "O índice é uma referência, não um investimento que você compra diretamente. Existem fundos que buscam acompanhá-lo, mas taxas e diferenças na carteira podem mudar o resultado." },
  { id: "inpc", name: "INPC", aliases: ["Índice Nacional de Preços ao Consumidor"], description: "Indicador de inflação calculado pelo IBGE com foco no consumo de famílias de menor renda. Acompanha mudanças de preços de produtos e serviços e pode ser usado como referência em reajustes de salários e benefícios, conforme a regra aplicável.", caution: "É diferente do IPCA porque considera outro perfil de famílias e pesos de consumo. Não representa exatamente a mudança nos gastos de cada pessoa." },
  { id: "inflacao", name: "Inflação", description: "Aumento dos preços de um conjunto de produtos e serviços ao longo do tempo, reduzindo o que o dinheiro consegue comprar. É medida por índices como IPCA, IGP-M e IGP-DI, que acompanham grupos de preços diferentes.", example: "Compras que custavam R$ 100 e passam a custar R$ 105 ficaram 5% mais caras. A mudança nos seus gastos pode ser diferente da inflação divulgada, porque você pode consumir outros produtos." },
  { id: "ipca", name: "IPCA", aliases: ["Índice Nacional de Preços ao Consumidor Amplo"], description: "Indicador calculado pelo IBGE para medir a mudança de preços de produtos e serviços consumidos pelas famílias incluídas na pesquisa. É a referência usada na meta de inflação do Brasil, mas não mede exatamente os gastos de cada pessoa.", caution: "Um investimento IPCA + taxa combina a variação desse índice com juros adicionais, conforme o contrato. Se você vender antes da data prevista para receber o dinheiro, pode obter um preço diferente do esperado, inclusive com perdas." },
  { id: "juros-compostos", name: "Juros compostos", description: "Juros calculados sobre o dinheiro inicial, chamado de capital, e também sobre os juros acumulados anteriormente. Por isso são conhecidos como juros sobre juros. Em um investimento com taxa positiva, o saldo cresce e os juros do próximo período são calculados sobre um valor maior.", formula: "Saldo final = valor inicial × (1 + taxa do período)^número de períodos", example: "R$ 1.000 a 1% ao mês ganham R$ 10 no primeiro mês e chegam a R$ 1.010. No segundo, 1% é calculado sobre R$ 1.010: são R$ 10,10 de juros, totalizando R$ 1.020,10.", caution: "Use a taxa em decimal: 1% = 0,01. Se a taxa é mensal, conte o prazo em meses. O símbolo ^ indica uma potência, isto é, multiplicações repetidas. Essa fórmula não inclui novos depósitos, retiradas, impostos ou tarifas." },
  { id: "lci", name: "LCI", aliases: ["Letra de Crédito Imobiliário"], description: "Investimento em que você empresta dinheiro a uma instituição financeira por meio de um título ligado ao crédito imobiliário. A instituição é responsável pelo pagamento. O contrato define os juros, a data de devolução e quando você pode retirar o dinheiro.", caution: "Confira impostos e a carência, período em que não é possível sacar. Pode contar com garantia do FGC nas condições e limites vigentes. Não é o mesmo que um CRI, que tem outra estrutura e não conta com essa garantia." },
  { id: "lca", name: "LCA", aliases: ["Letra de Crédito do Agronegócio"], description: "Investimento em que você empresta dinheiro a uma instituição financeira por meio de um título ligado ao crédito do agronegócio. A instituição é responsável pelo pagamento. O contrato define os juros, a data de devolução e quando você pode retirar o dinheiro.", caution: "Confira impostos e a carência, período em que não é possível sacar. Pode contar com garantia do FGC nas condições e limites vigentes. Não é o mesmo que um CRA, que tem outra estrutura e não conta com essa garantia." },
  { id: "liquidez", name: "Liquidez", description: "Facilidade de transformar um investimento em dinheiro disponível para usar. Leva em conta quanto tempo você precisa esperar, se há compradores e se precisa aceitar um preço menor ou pagar custos para sair do investimento.", caution: "Poder pedir um resgate em dias úteis, chamado de liquidez diária, não significa ausência de risco. Em bolsa, a quantidade de negociações e os preços oferecidos pelos compradores influenciam a venda." },
  { id: "lucro-por-acao", name: "Lucro por ação", aliases: ["LPA"], description: "Quanto do lucro da empresa corresponde a cada ação no cálculo. O lucro líquido é o que sobra das receitas depois de despesas e impostos. Dividir a parte desse lucro que pertence aos acionistas pela quantidade de ações ajuda a comparar resultados, mas não indica quanto será pago a cada investidor.", formula: "LPA simplificado = lucro líquido que pertence aos acionistas ÷ quantidade de ações", example: "Lucro de R$ 10 milhões dividido por 5 milhões de ações resulta em R$ 2 de lucro por ação. Isso não significa receber R$ 2 de dividendo.", caution: "Confira o período e a quantidade de ações considerada. A emissão de mais ações pode reduzir a parcela por ação, efeito chamado de diluição." },
  { id: "margem-liquida", name: "Margem líquida", description: "Percentual das vendas que sobra como lucro depois de todos os custos, despesas e impostos. A receita líquida é o valor das vendas após descontos, devoluções e impostos sobre vendas; o lucro líquido é o resultado que resta depois das demais despesas e impostos.", formula: "Margem líquida = lucro líquido ÷ receita líquida × 100", example: "Receita líquida de R$ 100 milhões e lucro líquido de R$ 10 milhões resultam em margem de 10%. Para cada R$ 100 de receita líquida, sobraram R$ 10 de lucro.", caution: "Compare empresas do mesmo setor. Ganhos que ocorreram uma única vez, como a venda de um imóvel, podem elevar a margem sem representar melhora das vendas habituais." },
  { id: "montante", name: "Montante", description: "Valor total acumulado em uma determinada data. Em um investimento, reúne o dinheiro aplicado e os ganhos ou perdas até aquele momento. Se o cálculo considerar retiradas, taxas ou impostos, esses valores também alteram o saldo.", example: "R$ 1.000 investidos mais R$ 100 de juros formam um montante de R$ 1.100, antes de descontar taxas ou impostos." },
  { id: "patrimonio-liquido", name: "Patrimônio líquido", aliases: ["PL"], description: "Diferença entre o que uma empresa ou fundo possui e tem a receber, chamado de ativos, e o que deve ou precisa pagar, chamado de passivos. É um valor dos registros contábeis, não necessariamente o dinheiro disponível na conta nem o preço pelo qual o negócio seria vendido.", formula: "Patrimônio líquido = ativos (bens e direitos) − passivos (dívidas e obrigações)", example: "Uma empresa registra R$ 500 milhões em bens e valores a receber e R$ 200 milhões em dívidas e obrigações. Seu patrimônio líquido é R$ 300 milhões." },
  { id: "p-l", name: "P/L", aliases: ["Preço sobre lucro"], description: "Compara o preço de uma ação com o lucro da empresa correspondente a cada ação, geralmente dos últimos 12 meses. Mostra quantas vezes esse lucro cabe no preço pago pela ação.", formula: "P/L = preço por ação ÷ lucro por ação", example: "Preço de R$ 30 e lucro por ação de R$ 3 resultam em P/L de 10 vezes: o preço equivale a dez vezes esse lucro.", caution: "Não é uma promessa de recuperar o investimento em dez anos, pois o lucro pode mudar e não é todo distribuído. Prejuízos, ganhos que ocorreram uma única vez e diferenças entre setores dificultam a comparação." },
  { id: "p-vp", name: "P/VP", aliases: ["Preço sobre valor patrimonial"], description: "Compara o preço de uma ação ou cota em bolsa com a parcela do patrimônio líquido que ela representa. O patrimônio líquido é o valor dos bens e direitos, menos dívidas e obrigações, registrado pela empresa ou fundo. O indicador mostra quanto você paga em relação a esse valor por ação ou cota.", formula: "P/VP = preço da ação ou cota ÷ valor patrimonial por ação ou cota", example: "Uma cota negociada a R$ 90 com valor patrimonial de R$ 100 tem P/VP de 0,90. O preço está 10% abaixo do valor patrimonial.", caution: "Abaixo de 1 não significa uma compra vantajosa garantida. Problemas nos bens e investimentos, dívidas ou expectativas ruins podem justificar o preço menor." },
  { id: "payout", name: "Payout", description: "Percentual do lucro que a empresa distribui aos acionistas em pagamentos como dividendos, chamados de proventos. Ajuda a entender quanto do lucro foi distribuído em vez de ficar na empresa.", formula: "Payout = valor distribuído referente ao período ÷ lucro do mesmo período × 100", example: "Uma empresa lucra R$ 10 milhões e distribui R$ 4 milhões referentes a esse lucro. Seu payout é 40%: foram distribuídos R$ 40 para cada R$ 100 de lucro.", caution: "Pagamentos que usam lucros guardados de anos anteriores podem fazer o indicador superar 100%. Lucro muito baixo ou negativo dificulta a interpretação. Confira quais pagamentos e períodos a fonte considera." },
  { id: "renda-fixa", name: "Renda fixa", description: "Investimentos cuja regra para calcular os juros é definida na contratação. Pode haver uma taxa conhecida desde o início, chamada de prefixada, uma taxa que acompanha um indicador, chamada de pós-fixada, ou uma combinação das duas. Regra definida não significa que o valor final seja sempre conhecido.", caution: "Você pode perder dinheiro se quem deve pagar não cumprir o contrato ou se precisar vender antes do prazo por um preço menor. Também pode não conseguir retirar o dinheiro quando precisar." },
  { id: "renda-variavel", name: "Renda variável", description: "Investimentos em que o ganho ou a perda não são definidos na contratação. O resultado depende de fatores como o desempenho das empresas, os pagamentos recebidos e os preços de compra e venda. Ações e cotas de fundos negociados em bolsa são exemplos.", caution: "Ganhos passados não garantem ganhos futuros. Você pode receber distribuições e, ainda assim, perder dinheiro se a queda do preço for maior que esses pagamentos." },
  { id: "rentabilidade", name: "Rentabilidade", description: "Ganho ou perda de um investimento em relação ao dinheiro usado como base, durante um período. A rentabilidade bruta é antes de custos e impostos; a líquida é depois desses descontos; a real considera também a inflação, para mostrar a mudança no que seu dinheiro consegue comprar.", formula: "Retorno sem novos depósitos ou retiradas = (valor final + pagamentos recebidos fora da aplicação − valor inicial) ÷ valor inicial × 100", example: "Você investe R$ 1.000, termina com R$ 1.080 na aplicação e recebe R$ 20 que não reinveste. O ganho total é R$ 100, ou 10% dos R$ 1.000 iniciais.", caution: "Não some novamente pagamentos já incluídos no saldo final. Com novos depósitos ou retiradas em datas diferentes, é necessário outro cálculo para medir corretamente o resultado." },
  { id: "reserva-emergencia", name: "Reserva de emergência", description: "Dinheiro guardado para despesas inesperadas ou períodos sem renda, como perda de emprego. A prioridade é conseguir usá-lo rapidamente e evitar grandes oscilações de valor, em vez de buscar o maior ganho possível.", example: "Se suas despesas essenciais são R$ 3.000 por mês, uma reserva para seis meses corresponde a R$ 18.000: 3.000 × 6.", caution: "Seis meses são apenas um exemplo, não uma regra para todos. Considere a estabilidade da sua renda, as pessoas que dependem de você e as despesas cobertas por seguros." },
  { id: "risco", name: "Risco", description: "Possibilidade de um investimento ter um resultado diferente do esperado, inclusive perda de dinheiro. Pode envolver não receber um pagamento, queda do preço, dificuldade para vender ou falhas em processos e sistemas.", caution: "Dividir o dinheiro entre investimentos diferentes, chamado de diversificação, reduz a dependência de um único investimento, mas não elimina todos os riscos." },
  { id: "roe", name: "ROE", aliases: ["Retorno sobre patrimônio líquido"], description: "Percentual que compara o lucro da empresa com seu patrimônio líquido, o valor dos bens e direitos menos as dívidas e obrigações. Ajuda a avaliar o lucro gerado em relação ao valor que pertence aos donos nos registros contábeis. O cálculo costuma usar a média desse patrimônio no período.", formula: "ROE = lucro líquido do período ÷ patrimônio líquido médio × 100", example: "Lucro de R$ 20 milhões e patrimônio líquido médio de R$ 100 milhões resultam em ROE de 20%: R$ 20 de lucro para cada R$ 100 de patrimônio.", caution: "Não é o retorno que você necessariamente ganha ao comprar a ação. O uso de dívidas para financiar o negócio pode aumentar o indicador e o risco. Patrimônio muito baixo ou negativo distorce a comparação; algumas fontes usam o valor do fim do período em vez da média." },
  { id: "selic", name: "Selic", description: "Taxa básica de juros usada pelo Banco Central para influenciar o crédito e a inflação no Brasil. O Copom, comitê do Banco Central responsável por essas decisões, define uma meta. A taxa efetiva é calculada a partir de operações de curto prazo entre instituições financeiras, com títulos públicos como garantia.", caution: "A meta Selic não é um ganho garantido na sua aplicação. O resultado após impostos e taxas depende das regras de cada investimento." },
  { id: "smll", name: "SMLL", aliases: ["Small caps", "Índice Small Cap"], description: "Índice da B3 que acompanha ações e units de empresas de menor valor de mercado, conhecidas como small caps. Valor de mercado é o preço das ações multiplicado pela quantidade de ações da empresa. O cálculo do índice considera mudanças de preços e pagamentos aos investidores.", caution: "Não significa simplesmente empresas com ações baratas: o preço de uma ação sozinho não mede o tamanho da companhia. O índice tem regras de seleção e pode oscilar bastante." },
  { id: "spread", name: "Spread", description: "Diferença entre duas taxas ou dois preços. Em empréstimos, pode comparar os juros cobrados pelo banco com o custo que ele tem para obter o dinheiro. Em bolsa, pode indicar a distância entre o maior preço que um comprador oferece e o menor preço que um vendedor aceita.", example: "Se a melhor oferta de compra é R$ 99 e a melhor oferta de venda é R$ 100, o spread é R$ 1. As ofertas ainda não se encontram nesse momento.", caution: "No crédito, essa diferença não é toda lucro do banco: também precisa cobrir despesas, impostos e perdas com pagamentos não recebidos." },
  { id: "taxa-equivalente", name: "Taxa equivalente", description: "Taxa expressa em outro prazo que produz o mesmo resultado acumulado com juros compostos, ou seja, juros sobre juros. Serve, por exemplo, para transformar uma taxa anual em mensal sem alterar o crescimento ao longo de um ano. Não basta dividir por 12, porque os juros de cada mês entram no cálculo dos meses seguintes.", formula: "Taxa mensal equivalente = (1 + taxa anual)^(1/12) − 1", example: "12% ao ano equivalem a aproximadamente 0,9489% ao mês. Aplicadas por 12 meses com juros compostos, as duas taxas produzem o mesmo crescimento, antes de custos.", caution: "Na fórmula, escreva 12% como 0,12. A potência 1/12 encontra o fator mensal que, multiplicado por si mesmo 12 vezes, reproduz o fator anual. Multiplique o resultado por 100 para exibi-lo em percentual." },
  { id: "taxa-real", name: "Taxa real", aliases: ["Juro real", "Juros reais", "Juros real", "Rentabilidade real"], description: "Ganho ou perda depois de considerar a inflação. Mostra a mudança no poder de compra do dinheiro. Não é a mesma coisa que retorno líquido, que desconta custos e impostos.", formula: "Taxa real = [(1 + taxa nominal) ÷ (1 + inflação) − 1] × 100", example: "Ganho nominal de 14% e inflação de 10% no mesmo ano resultam em cerca de 3,64% reais: (1,14 ÷ 1,10 − 1) × 100.", caution: "Use taxas em decimal: 14% = 0,14. Compare o mesmo período e desconte custos e impostos quando aplicáveis. Consulte a inflação no IBGE ou no responsável pelo índice usado." },
  { id: "ticker", name: "Ticker", aliases: ["Código de negociação"], description: "Código usado para localizar e negociar um investimento em bolsa. Na B3, a bolsa brasileira, normalmente combina letras e números. Você usa esse código para procurar uma ação, uma unit ou uma cota de fundo na plataforma da corretora.", example: "BBAS3, PETR4, TAEE11, BOVA11, HGLG11.", caution: "O final 11 não identifica sozinho o tipo de investimento: pode aparecer em units, ETFs e FIIs. Confira o nome e a categoria antes de negociar." },
  { id: "unit", name: "Unit", aliases: ["Units", "Certificado de depósito de ações"], description: "Certificado comprado e vendido em bolsa que reúne um conjunto de ações de uma mesma empresa. Geralmente combina ações ordinárias, que em regra permitem votar, e preferenciais, que têm preferências previstas nas regras da empresa. A companhia define quantas ações de cada tipo formam uma unit.", example: "TAEE11 (1 TAEE3 + 2 TAEE4).", caution: "A composição varia entre empresas. Confira os direitos das ações reunidas no certificado. Uma unit não divide seu dinheiro entre empresas diferentes nem garante ganhos." },
  { id: "vacancia", name: "Vacância", description: "Parte dos imóveis que está desocupada ou que deixa de gerar a receita de aluguel usada como referência. A vacância física mede a área vaga em relação à área total disponível para alugar. A financeira considera a receita que não é recebida em relação à receita potencial, conforme os critérios do relatório.", formula: "Vacância física = área desocupada ÷ área total disponível para alugar × 100", example: "Se um imóvel tem 10.000 m² disponíveis para alugar e 1.000 m² estão vazios, sua vacância física é 10%: 1.000 ÷ 10.000 × 100.", caution: "A área vazia pode ter aluguel por metro quadrado diferente da área ocupada. Por isso, 10% de área desocupada não significa necessariamente 10% de perda de receita. Confira o cálculo usado pelo fundo." },
  { id: "valor-patrimonial-cota", name: "Valor patrimonial por cota", aliases: ["VPC", "VP por cota"], description: "Valor dos bens, investimentos e direitos de um fundo, menos suas dívidas e obrigações, dividido pela quantidade de cotas. Mostra a parcela do patrimônio líquido que corresponde a cada cota nos registros do fundo. Em FIIs, pode incluir avaliações dos imóveis, que não são dinheiro disponível na conta.", formula: "Valor patrimonial por cota = patrimônio líquido do fundo ÷ quantidade de cotas", example: "Um fundo com patrimônio líquido de R$ 500 milhões e 5 milhões de cotas tem valor patrimonial de R$ 100 por cota: 500 milhões ÷ 5 milhões.", caution: "Esse valor não garante quanto você receberia ao vender ou resgatar uma cota. Em bolsa, o preço depende das ofertas de compradores e vendedores e pode ser diferente." },
  { id: "volatilidade", name: "Volatilidade", description: "Medida de quanto os ganhos e perdas de um investimento variam ao longo de um período. Um investimento cujo preço sobe e cai de forma mais intensa tende a ter maior volatilidade que outro com movimentos mais estáveis.", caution: "Não mede todos os riscos. Um investimento pode oscilar pouco e, ainda assim, ter risco de não pagar o que deve ou ser difícil de vender." },
  { id: "tesouro-direto", name: "Tesouro Direto", description: "Programa que permite comprar títulos do governo federal. Ao investir, você empresta dinheiro ao governo e recebe conforme as regras do título escolhido.", caution: "Há impostos e possíveis taxas. A venda antes do prazo ocorre pelo preço de mercado, que pode ser menor que o valor investido." },
  { id: "tesouro-selic", name: "Tesouro Selic", aliases: ["LFT"], description: "Título público cujo rendimento acompanha a Selic. Costuma oscilar menos que títulos prefixados ou ligados ao IPCA, sendo usado para objetivos de curto prazo e reservas de emergência.", caution: "Não é dinheiro disponível a qualquer hora: confira os prazos de resgate. Pode oscilar e tem custos e impostos." },
  { id: "tesouro-ipca", name: "Tesouro IPCA+", aliases: ["NTN-B", "Tesouro IPCA"], description: "Título público que combina a variação do IPCA com uma taxa de juros definida na compra. Busca preservar o poder de compra e gerar ganho adicional antes de custos e impostos, seguindo os pagamentos previstos.", caution: "A taxa contratada vale para o fluxo previsto se o título for mantido. Vender antes pode causar perdas. Há versões com pagamentos de juros durante o prazo." },
  { id: "tesouro-educa", name: "Tesouro Educa+", aliases: ["Tesouro Educa", "NTN-B1"], description: "Título público para planejar despesas de educação. Acumula recursos e depois devolve o investimento com os rendimentos em 60 pagamentos mensais, durante cinco anos, corrigidos pelo IPCA.", caution: "A renda depende do valor acumulado e da taxa contratada. Não garante pagar todos os estudos; vender antes do fluxo previsto pode causar perdas." },
  { id: "tesouro-renda", name: "Tesouro RendA+", aliases: ["Tesouro Renda", "NTN-B1"], description: "Título público para planejar uma renda complementar na aposentadoria. Após a fase de acumulação, devolve o investimento com os rendimentos em 240 pagamentos mensais, durante 20 anos, corrigidos pelo IPCA.", caution: "Não é renda vitalícia: os pagamentos terminam. O valor depende do investimento e da taxa contratada; vender antes do fluxo previsto pode causar perdas." },
  { id: "tesouro-prefixado", name: "Tesouro Prefixado", aliases: ["LTN", "NTN-F"], description: "Título público com taxa de juros definida na compra. Permite conhecer os pagamentos antes de custos e impostos se você mantiver o título até o fim do prazo previsto.", caution: "A taxa não acompanha a inflação. Na venda antecipada, o resultado pode ser diferente do contratado, inclusive com perdas. Há versões com pagamentos de juros durante o prazo." },
  { id: "indexador", name: "Indexador", description: "Referência usada para atualizar um valor ou calcular juros. Pode aparecer em investimentos, empréstimos e contratos de aluguel.", example: "CDI, Selic, IPCA e IGP-M.", caution: "Confira o percentual, o período e a regra do contrato. Uma referência de reajuste não é uma promessa de ganho." },
  { id: "ibra", name: "IBRA", aliases: ["Índice Brasil Amplo"], description: "Índice da B3 que acompanha uma carteira ampla de ações e units selecionadas por critérios de negociação. Oferece uma visão do mercado brasileiro além dos índices com quantidade fixa de ativos." },
  { id: "ibrx-50", name: "IBrX 50", aliases: ["IBXL", "Índice Brasil 50"], description: "Índice da B3 que acompanha 50 ações e units selecionadas por critérios de negociação e presença em bolsa. É uma referência mais concentrada que o IBrX 100." },
  { id: "ico2", name: "ICO2", aliases: ["Índice Carbono Eficiente"], description: "Índice da B3 que considera a divulgação e a eficiência das emissões de gases de efeito estufa das empresas. Esses critérios influenciam a participação de cada empresa na carteira.", caution: "Estar no índice não significa emitir zero carbono nem garante valorização." },
  { id: "icon", name: "ICON", aliases: ["Índice de Consumo"], description: "Índice da B3 que acompanha empresas de consumo e saúde, como varejistas, fabricantes de alimentos e prestadoras de serviços desses setores." },
  { id: "iee", name: "IEE", aliases: ["IEEX", "Índice de Energia Elétrica"], description: "Índice da B3 que acompanha empresas do setor elétrico, como geração, transmissão e distribuição de energia." },
  { id: "ifnc", name: "IFNC", aliases: ["Índice Financeiro"], description: "Índice da B3 que acompanha empresas financeiras, como bancos, seguradoras e prestadoras de serviços financeiros." },
  { id: "igct", name: "IGCT", aliases: ["Índice de Governança Corporativa Trade"], description: "Índice da B3 que seleciona ações do IGC com critérios adicionais de negociação. Reúne empresas de segmentos com regras diferenciadas de transparência e proteção aos acionistas." },
  { id: "igc", name: "IGC", aliases: ["IGCX", "Índice de Ações com Governança Corporativa Diferenciada"], description: "Índice da B3 que acompanha empresas do Novo Mercado, Nível 1 e Nível 2, segmentos com exigências adicionais de transparência e direitos dos acionistas.", caution: "Essas regras não garantem boa gestão, ausência de problemas ou retorno do investimento." },
  { id: "ignm", name: "IGNM", aliases: ["IGC-NM", "Índice de Governança Corporativa – Novo Mercado"], description: "Índice da B3 que acompanha ações de empresas do Novo Mercado, segmento com regras adicionais de transparência e proteção aos acionistas.", caution: "Participar do Novo Mercado não elimina os riscos do negócio ou da ação." },
  { id: "imat", name: "IMAT", aliases: ["Índice de Materiais Básicos"], description: "Índice da B3 que acompanha empresas de materiais básicos, como mineração, siderurgia, papel, celulose e produtos químicos." },
  { id: "imob", name: "IMOB", aliases: ["Índice Imobiliário"], description: "Índice da B3 que acompanha ações de empresas do setor imobiliário, como incorporadoras, construtoras e empresas de exploração de imóveis.", caution: "Não é um índice de fundos imobiliários. Para FIIs, a referência mais conhecida é o IFIX." },
  { id: "indx", name: "INDX", aliases: ["Índice do Setor Industrial"], description: "Índice da B3 que acompanha ações de empresas de diferentes segmentos da indústria. Serve como referência para o desempenho desse conjunto de negócios." },
  { id: "ise", name: "ISE", aliases: ["ISEE", "ISE B3", "Índice de Sustentabilidade Empresarial"], description: "Índice da B3 que seleciona empresas por critérios de sustentabilidade, incluindo questões ambientais, sociais e de gestão.", caution: "A seleção segue a metodologia do índice, não uma garantia de impacto positivo ou ganho financeiro." },
  { id: "itag", name: "ITAG", aliases: ["Índice de Ações com Tag Along Diferenciado"], description: "Índice da B3 que acompanha empresas com condições diferenciadas de proteção aos acionistas minoritários, que não controlam a empresa, quando seu controle é vendido." },
  { id: "tag-along", name: "Tag along", description: "Direito de acompanhar a venda do controle de uma empresa, vendendo suas ações nas condições previstas para seu tipo de ação. Protege acionistas que não controlam a companhia.", caution: "O percentual e as condições variam conforme a lei, o tipo de ação e as regras da empresa. Não garante o preço de venda no dia a dia." },
  { id: "ivbx-2", name: "IVBX 2", aliases: ["IVBX", "Índice Valor"], description: "Índice da B3 e do jornal Valor Econômico que seleciona 50 ativos. Exclui os dez mais negociados e os de empresas com os dez maiores valores de mercado, conforme sua metodologia." },
  { id: "mlcx", name: "MLCX", aliases: ["Índice MidLarge Cap"], description: "Índice da B3 que acompanha ações e units de empresas de médio e grande valor de mercado. Complementa o SMLL, voltado às empresas menores." },
  { id: "util", name: "UTIL", aliases: ["Índice Utilidade Pública"], description: "Índice da B3 que acompanha empresas de serviços de utilidade pública, como energia elétrica, água, saneamento e gás." },
  { id: "suno-30", name: "Suno 30", aliases: ["SNFI", "SUNO30"], description: "Índice criado pela Suno Research que acompanha uma carteira de 30 fundos imobiliários selecionados por sua metodologia. É uma referência alternativa ao IFIX.", caution: "É um índice, não uma cota de fundo. Sua carteira e suas regras diferem das do IFIX." },
  { id: "xpfi", name: "XPFI", aliases: ["Índice XP de Fundos Imobiliários"], description: "Índice da XP que acompanha uma carteira de fundos imobiliários selecionados por critérios de negociação. Serve como referência para comparar resultados de FIIs.", caution: "É diferente do IFIX e não representa todos os fundos imobiliários." },
  { id: "xpfp", name: "XPFP", aliases: ["Índice XP de Fundos Imobiliários de Papel"], description: "Índice da XP que acompanha FIIs de papel, fundos que investem principalmente em títulos e valores a receber ligados ao mercado imobiliário, como CRIs." },
  { id: "xpft", name: "XPFT", aliases: ["Índice XP de Fundos Imobiliários de Tijolo"], description: "Índice da XP que acompanha FIIs de tijolo, fundos voltados principalmente a imóveis físicos, como galpões, escritórios e shopping centers." },
  { id: "bdr", name: "BDR", aliases: ["Brazilian Depositary Receipt", "Brazilian Depositary Receipts"], description: "Certificado negociado no Brasil que representa um ativo emitido no exterior e mantido em custódia, ou seja, guardado por uma instituição responsável. Dá acesso ao investimento estrangeiro sem comprá-lo diretamente fora do país.", caution: "Não é uma ação brasileira da empresa estrangeira. O preço varia com o ativo representado e o câmbio." },
  { id: "bdrx", name: "BDRX", aliases: ["Índice de BDRs Não Patrocinados – GLOBAL"], description: "Índice da B3 que acompanha BDRs não patrocinados. São certificados de ativos estrangeiros criados por uma instituição depositária sem participação do emissor estrangeiro.", caution: "Reflete tanto o desempenho dos ativos quanto efeitos do câmbio. Não é um índice de empresas brasileiras." },
  { id: "sp-midcap-400", name: "S&P MidCap 400", aliases: ["MID", "S&P MIDCAP", "S&P 400"], description: "Índice da S&P Dow Jones Indices que acompanha 400 empresas de médio porte dos Estados Unidos, selecionadas por sua metodologia." },
  { id: "sp-100", name: "S&P 100", aliases: ["OEX"], description: "Índice da S&P Dow Jones Indices que acompanha 100 grandes empresas dos Estados Unidos. É um grupo selecionado dentro do S&P 500." },
  { id: "sp-500", name: "S&P 500", aliases: ["SPX"], description: "Índice da S&P Dow Jones Indices que acompanha 500 grandes empresas dos Estados Unidos. É uma das principais referências do mercado de ações americano.", caution: "O resultado de um investimento em reais também pode mudar com o câmbio, além de custos e diferenças em relação ao índice." },
  { id: "fundo-investimento", name: "Fundo de investimento", aliases: ["Fundos de investimentos"], description: "Reúne dinheiro de investidores para aplicar segundo regras definidas. Cada investidor possui cotas, e um gestor decide as aplicações dentro da estratégia do fundo.", caution: "Confira taxas, riscos e prazos para retirar o dinheiro. Fundos não têm garantia do FGC." },
  { id: "fiagro", name: "Fiagro", aliases: ["Fundo de Investimento nas Cadeias Produtivas Agroindustriais"], description: "Fundo que investe em atividades do agronegócio, por exemplo em imóveis rurais, empresas e títulos ligados ao setor. A estratégia depende das regras de cada fundo.", caution: "Há riscos de crédito, clima, preços agrícolas e venda das cotas. Não tem garantia do FGC." },
  { id: "fia", name: "FIA", aliases: ["Fundo de Investimento em Ações"], description: "Fundo cuja carteira é voltada principalmente a ações e outros ativos admitidos nessa categoria. O gestor escolhe os investimentos conforme a estratégia do fundo.", caution: "Pode perder valor com a queda das ações. Não garante retorno nem tem proteção do FGC." },
  { id: "fidc", name: "FIDC", aliases: ["Fundo de Investimento em Direitos Creditórios"], description: "Fundo que investe em valores a receber, como parcelas de vendas, empréstimos ou faturas. Esses direitos de receber dinheiro são chamados de direitos creditórios.", caution: "Atrasos ou falta de pagamento podem causar perdas. Confira os tipos de cota, pois podem ter riscos e prioridades de pagamento diferentes." },
  { id: "fip", name: "FIP", aliases: ["Fundo de Investimento em Participações"], description: "Fundo que investe em participações em empresas e atua nas suas decisões conforme as regras aplicáveis. Pode financiar negócios que ainda não têm ações negociadas em bolsa.", caution: "Pode exigir prazos longos e ser difícil de vender. Confira restrições de acesso e riscos do regulamento." },
  { id: "fi-infra", name: "FI-Infra", aliases: ["FI Infra", "Fundo de Investimento em Infraestrutura", "Fundo Incentivado de Investimento em Infraestrutura"], description: "Fundo de renda fixa que investe em títulos de dívida ligados a projetos de infraestrutura, como energia, transporte e saneamento. Não é o mesmo que um FIP de infraestrutura.", caution: "As empresas financiadas podem atrasar pagamentos, e os títulos podem cair de preço. Não tem garantia do FGC." },
  { id: "fii-papel", name: "FII de papel", aliases: ["Fundos de papel", "Fundos de papéis"], description: "Fundo imobiliário que investe principalmente em títulos e valores a receber do setor, como CRIs, em vez de comprar imóveis físicos.", caution: "Papel é um apelido para esses investimentos, não a existência de um certificado impresso. Os rendimentos dependem dos pagamentos; não há renda mensal garantida." },
  { id: "fii-tijolo", name: "FII de tijolo", aliases: ["Fundos de tijolo", "Fundos de tijolos"], description: "Fundo imobiliário voltado principalmente a imóveis físicos, como galpões, escritórios, shopping centers, hospitais e hotéis. Pode receber receitas de aluguel e de venda dos imóveis.", caution: "Imóveis vazios, atrasos de aluguel e despesas podem reduzir os rendimentos." },
  { id: "criptoativo", name: "Criptoativo", description: "Ativo digital que usa criptografia e pode ser registrado em uma blockchain. É um grupo amplo que inclui criptomoedas e outros tokens, com funções e riscos diferentes.", example: "Bitcoin (BTC), ether (ETH) e tokens como USDT.", caution: "Nem todo criptoativo funciona como dinheiro ou é descentralizado. Pode haver perdas, fraudes e restrições de negociação." },
  { id: "criptomoeda", name: "Criptomoeda", aliases: ["Criptomoedas"], description: "Tipo de criptoativo usado para transferir valor em uma rede digital. As regras de emissão e validação dependem de cada projeto, e nem todas as moedas têm o mesmo nível de descentralização.", example: "Bitcoin (BTC), ether (ETH), litecoin (LTC) e ADA.", caution: "Os preços podem variar muito. Usar criptografia não garante valor, segurança de plataformas ou ausência de interferência regulatória." },
  { id: "bitcoin", name: "Bitcoin", aliases: ["BTC"], description: "Criptomoeda de uma rede que permite transferir valor sem um banco central emissor. Suas regras preveem emissão limitada a 21 milhões de bitcoins.", example: "BTC.", caution: "A quantidade limitada não garante valorização. É possível comprar frações de bitcoin, e o preço pode cair bastante." },
  { id: "ethereum", name: "Ethereum", aliases: ["Ether", "ETH"], description: "Rede blockchain que permite executar programas e criar ativos digitais. Ether (ETH) é sua criptomoeda, usada para pagar operações e participar da segurança da rede.", example: "ETH.", caution: "Rede e moeda não são a mesma coisa. O ETH não tem um limite máximo fixo de emissão; seu preço e as taxas de uso variam." },
  { id: "tether", name: "Tether", aliases: ["USDT"], description: "USDT é uma stablecoin emitida pela Tether que busca acompanhar o dólar americano. Usa reservas administradas pelo emissor para sustentar essa referência.", example: "USDT.", caution: "Não é dólar em uma conta bancária nem tem garantia do FGC. Há riscos nas reservas, no emissor e na manutenção do valor de referência." },
  { id: "litecoin", name: "Litecoin", aliases: ["LTC"], description: "Criptomoeda criada a partir de ideias e código do Bitcoin, voltada à transferência de valor. Suas regras preveem emissão limitada a 84 milhões de moedas.", example: "LTC.", caution: "O limite de emissão não garante preço estável ou valorização." },
  { id: "cardano", name: "Cardano", aliases: ["ADA"], description: "Rede blockchain que permite transferências e programas automáticos. ADA é sua criptomoeda, usada em operações e na participação na segurança da rede.", example: "ADA.", caution: "O preço pode oscilar, e a adoção da rede não garante ganhos para quem compra ADA." },
  { id: "stablecoin", name: "Stablecoin", aliases: ["Stablecoins"], description: "Criptoativo que busca manter o valor ligado a uma referência, como o dólar. Pode usar reservas ou outros mecanismos, que variam entre projetos.", example: "USDT e USDC, ligados ao dólar.", caution: "Pode perder a ligação com o valor de referência. Não equivale a dinheiro sem risco; confira o emissor, as reservas e as regras." },
  { id: "memecoin", name: "Memecoin", aliases: ["Memecoins", "Meme coin"], description: "Criptoativo associado a memes, personagens ou comunidades da internet. Seu preço costuma depender muito da atenção nas redes e da especulação.", example: "Dogecoin (DOGE) e Shiba Inu (SHIB).", caution: "Pode sofrer quedas fortes e manipulação de preços. Popularidade não garante utilidade ou valor." },
  { id: "altcoin", name: "Altcoin", aliases: ["Altcoins"], description: "Nome usado para criptomoedas diferentes do Bitcoin. É um grupo amplo, com projetos de funções e riscos muito distintos.", example: "Ether (ETH), litecoin (LTC) e ADA.", caution: "Ser uma alternativa ao Bitcoin não significa ser melhor, mais segura ou mais barata." },
  { id: "token", name: "Token", aliases: ["Tokens"], description: "Unidade digital registrada em uma blockchain. Pode representar acesso a serviços, direitos, valor ou participação em decisões, conforme as regras do projeto.", example: "USDT, USDC, UNI e AAVE.", caution: "O nome token não garante propriedade de um bem nem direitos legais. Confira o que ele realmente representa." },
  { id: "token-utilidade", name: "Token de utilidade", aliases: ["Utility token"], description: "Token usado para acessar ou pagar funções de um projeto, como serviços, armazenamento ou operações. O uso específico depende das regras da plataforma.", example: "Basic Attention Token (BAT), ligado a serviços de publicidade no ecossistema Brave.", caution: "Ter uma função no projeto não garante demanda ou valorização." },
  { id: "token-governanca", name: "Token de governança", aliases: ["Governance token"], description: "Token que permite participar de votações sobre um projeto, conforme suas regras. Não equivale automaticamente a uma ação de empresa ou a um direito de receber lucros.", example: "UNI, do Uniswap, e AAVE, do Aave.", caution: "O poder de voto pode ser concentrado, e as decisões nem sempre abrangem todo o projeto." },
  { id: "blockchain", name: "Blockchain", description: "Sistema que registra informações em blocos ligados entre si e validados conforme as regras de uma rede. Em redes públicas, permite conferir transações sem depender de um único registro central.", example: "Redes Bitcoin, Ethereum e Cardano.", caution: "Um registro na blockchain não prova que uma informação externa é verdadeira. Redes podem ter diferentes níveis de controle e segurança." },
  { id: "contrato-inteligente", name: "Contrato inteligente", aliases: ["Smart contract"], description: "Programa em uma blockchain que executa ações conforme condições definidas no código. Pode automatizar trocas, empréstimos e outras operações.", caution: "Pode ter erros ou depender de dados externos incorretos. Não é necessariamente um contrato jurídico nem dispensa confiança em pessoas e sistemas." },
  { id: "defi", name: "DeFi", aliases: ["Finanças descentralizadas", "Decentralized finance"], description: "Serviços financeiros em blockchain que usam programas para operações como trocas e empréstimos, sem funcionar como um banco tradicional.", example: "Uniswap (token UNI) e Aave (token AAVE).", caution: "O grau de descentralização varia. Erros de código, falta de recursos e perdas nas garantias podem causar prejuízo." },
  { id: "nft", name: "NFT", aliases: ["Token não fungível"], description: "Token com identificação própria, que não é intercambiável com outro equivalente como uma moeda. Pode representar itens colecionáveis, ingressos ou direitos definidos pelo projeto.", example: "Um token que identifica um item de um jogo.", caution: "Não garante direitos autorais, exclusividade sobre uma imagem ou facilidade de revenda." },
  { id: "carteira-cripto", name: "Carteira de criptoativos", aliases: ["Wallet", "Carteira cripto"], description: "Ferramenta para consultar e movimentar criptoativos por meio das chaves que autorizam transações. Os registros dos ativos ficam na rede, não dentro do aplicativo ou dispositivo.", caution: "Na custódia própria, perder as chaves pode impedir o acesso. Em serviços de terceiros, você depende da segurança e das regras do prestador." },
  { id: "chave-privada", name: "Chave privada", description: "Código secreto que autoriza a movimentação de criptoativos ligados a um endereço. Quem tem acesso a ele pode controlar esses ativos.", caution: "Não compartilhe a chave nem a frase de recuperação que permite restaurá-la. Perda ou vazamento podem causar perda dos ativos." },
  { id: "exchange", name: "Exchange", aliases: ["Corretora de criptoativos"], description: "Plataforma para comprar, vender ou trocar criptoativos. Pode ser operada por uma empresa ou funcionar por programas em blockchain.", caution: "Confira taxas, regras de saque e quem guarda os ativos. Falhas, fraudes ou bloqueios podem impedir o acesso ao dinheiro." },
  { id: "staking", name: "Staking", description: "Participação na validação de uma rede por meio de moedas usadas como garantia, diretamente ou por delegação. Pode gerar recompensas conforme as regras da rede.", example: "ETH na Ethereum e ADA na Cardano.", caution: "Não é renda fixa. Preço, prazos de retirada, penalidades e riscos de intermediários variam; nem toda oferta chamada staking valida uma rede." },
  { id: "proof-of-stake", name: "Proof of stake", aliases: ["PoS", "Prova de participação"], description: "Método de validação em que participantes usam moedas como garantia para propor ou confirmar blocos. As recompensas e possíveis penalidades dependem da rede.", example: "Ethereum e Cardano." },
  { id: "proof-of-work", name: "Proof of work", aliases: ["PoW", "Prova de trabalho", "Mineração"], description: "Método de validação em que computadores realizam trabalho de cálculo para disputar a criação de blocos. É conhecido como mineração e envolve gasto de energia.", example: "Bitcoin e Litecoin." },
  { id: "gas", name: "Gas", aliases: ["Taxa de rede"], description: "Medida do trabalho necessário para executar uma operação em redes como a Ethereum. O custo depende do trabalho usado e do preço do gas naquele momento.", caution: "O valor pode variar, e uma operação que falha também pode consumir gas e gerar custo." },
  { id: "fomo", name: "FOMO", aliases: ["Fear of missing out", "Medo de ficar de fora"], description: "Medo de perder uma oportunidade ou ficar de fora de um movimento. Pode levar a comprar por impulso, sem avaliar preço, riscos ou objetivos.", example: "Comprar bitcoin só porque o preço subiu e outras pessoas dizem estar ganhando dinheiro.", caution: "A pressa e a popularidade não tornam um investimento adequado para você." },
  { id: "meta", name: "Meta", description: "Resultado específico que você quer atingir, com uma medida e um prazo. Transforma uma intenção em algo que pode ser acompanhado.", example: "Guardar R$ 12.000 em 12 meses, separando R$ 1.000 por mês." },
  { id: "objetivo", name: "Objetivo", description: "O que você pretende alcançar e por quê. Orienta as decisões; as metas definem valores e prazos para chegar até ele.", example: "Ter uma reserva para manter as despesas durante um período sem emprego." },
  { id: "sonho", name: "Sonho", description: "Desejo que inspira seu planejamento, mas ainda pode não ter valor, prazo ou ações definidos. Pode se transformar em um objetivo e depois em metas.", example: "Viajar pelo mundo. Para planejar, escolha destinos, estime os custos e defina quando quer viajar." },
  { id: "milestone", name: "Milestone", aliases: ["Marco", "Marcos"], description: "Ponto importante de progresso dentro de um plano. Ajuda a dividir um objetivo maior em etapas e perceber o que já foi alcançado.", example: "Chegar aos primeiros R$ 10.000 de uma meta de R$ 50.000." },
  { id: "ativos", name: "Ativos", aliases: ["Ativo"], description: "Bens e direitos com valor econômico que uma pessoa, empresa ou fundo possui. Incluem dinheiro, investimentos, imóveis e valores a receber.", example: "Saldo em conta, ações e um imóvel são ativos.", caution: "Um ativo não precisa gerar renda todo mês: também pode ter despesas ou perder valor." },
  { id: "passivos", name: "Passivos", aliases: ["Passivo"], description: "Dívidas e obrigações que uma pessoa, empresa ou fundo precisa pagar. São diferentes dos bens que possui, chamados de ativos.", example: "Saldo de um financiamento, empréstimos e contas a pagar.", caution: "Um imóvel financiado é um ativo; a dívida do financiamento é um passivo." },
  { id: "smart", name: "SMART", aliases: ["S.M.A.R.T", "S.M.A.R.T.", "Metas SMART"], description: "Método para definir metas específicas, mensuráveis, atingíveis, relevantes e com prazo. Ajuda a verificar o que fazer, como medir e até quando concluir.", example: "Guardar R$ 6.000 para uma reserva em 12 meses, com R$ 500 por mês, se esse valor couber no orçamento." },
  { id: "roadmap", name: "Roadmap", aliases: ["Plano de etapas"], description: "Visão das etapas de um plano e da ordem em que serão realizadas. Conecta ações, prazos e marcos ao objetivo final.", example: "Organizar o orçamento, quitar dívidas caras e formar uma reserva, revisando o plano a cada etapa." },
  { id: "boletim-focus", name: "Boletim Focus", aliases: ["Relatório Focus", "Focus"], description: "Relatório do Banco Central que resume projeções de participantes do mercado para inflação, PIB, câmbio e juros. É publicado semanalmente.", caution: "São expectativas dos participantes da pesquisa, não previsões garantidas nem compromissos do Banco Central." },
  { id: "pib", name: "PIB", aliases: ["Produto Interno Bruto"], description: "Valor dos bens e serviços finais produzidos em um país ou região em determinado período. Usar os produtos finais evita contar várias vezes as etapas da mesma produção.", caution: "Não é a riqueza acumulada nem a renda de cada pessoa. O PIB real desconta o efeito da mudança de preços para medir crescimento." },
  { id: "copom", name: "Copom", aliases: ["Comitê de Política Monetária"], description: "Comitê do Banco Central que define a meta da taxa Selic. Suas decisões buscam manter a inflação em linha com a meta estabelecida.", caution: "A meta Selic influencia outras taxas, mas não determina diretamente todos os juros cobrados por bancos." },
  { id: "selic-meta", name: "Selic meta", aliases: ["Meta Selic", "Selic (Meta)"], description: "Taxa de juros definida pelo Copom como referência da política monetária. O Banco Central atua para manter a taxa efetiva das operações próxima dessa meta.", caution: "Não é o rendimento líquido garantido de uma aplicação." },
  { id: "selic-over", name: "Selic over", aliases: ["Selic efetiva", "Selic (Over)", "Overnight"], description: "Taxa efetiva calculada a partir de operações de um dia útil com títulos públicos federais. Reflete as operações realizadas, enquanto a Selic meta é definida pelo Copom.", caution: "Costuma ficar próxima da meta, mas a diferença não é uma regra fixa de 0,1 ponto percentual." },
  { id: "taxa-juros", name: "Taxa de juros", aliases: ["Taxas de juros"], description: "Percentual que determina o custo de usar dinheiro emprestado ou a remuneração de um investimento em um período.", example: "1% ao mês sobre R$ 1.000 corresponde a R$ 10 de juros nesse mês, antes de outros custos.", caution: "Confira se a taxa é mensal ou anual e como é aplicada. Para dívidas, avalie também o CET." },
  { id: "risco-sistematico", name: "Risco sistemático", aliases: ["Risco não diversificável"], description: "Risco ligado a fatores amplos que afetam muitos investimentos, como crises econômicas, mudanças de juros ou pandemias.", caution: "Ter vários investimentos não elimina esse risco. Os efeitos podem ser diferentes em cada ativo." },
  { id: "risco-nao-sistematico", name: "Risco não sistemático", aliases: ["Risco específico", "Risco diversificável"], description: "Risco próprio de uma empresa, setor ou investimento, como problemas de gestão ou perda de um grande cliente. Pode ser reduzido dividindo o dinheiro entre investimentos com riscos diferentes.", caution: "Uma mudança pode afetar vários setores ao mesmo tempo. A classificação depende da origem e da abrangência do problema." },
  { id: "diversificacao", name: "Diversificação", description: "Distribuir investimentos entre ativos, empresas, setores ou mercados com riscos diferentes. Reduz a dependência de um único resultado.", example: "Evitar concentrar todo o dinheiro em ações de uma empresa ou em títulos de um único banco.", caution: "Não elimina perdas nem o risco sistemático. Não existe um número universal, como 16 ativos: a composição e o quanto os investimentos se movem juntos importam." },
  { id: "risco-credito", name: "Risco de crédito", description: "Risco de quem deve pagar atrasar ou não devolver o dinheiro combinado. Existe em empréstimos, títulos de dívida e outros valores a receber.", example: "Uma empresa não pagar os juros ou a devolução prevista de uma debênture." },
  { id: "risco-mercado", name: "Risco de mercado", description: "Risco de perda com mudanças nos preços, juros, câmbio ou outras condições de mercado. Pode afetar ações, fundos e títulos de renda fixa.", example: "Precisar vender um título antes do prazo quando seu preço está abaixo do valor pago." },
  { id: "risco-liquidez", name: "Risco de liquidez", description: "Risco de não conseguir transformar um investimento em dinheiro no momento necessário ou sem aceitar um preço muito menor.", example: "Precisar vender um imóvel rapidamente e não encontrar comprador pelo preço esperado." },
  { id: "risco-operacional", name: "Risco operacional", description: "Risco de perdas causadas por falhas em pessoas, processos ou sistemas, além de eventos externos que prejudicam a operação.", example: "Fraude, erro em uma transferência ou falha de um sistema de negociação." },
  { id: "risco-legal", name: "Risco legal", aliases: ["Risco jurídico", "Risco regulatório"], description: "Risco de perdas por problemas com contratos, descumprimento de leis ou mudanças nas regras que afetam uma operação.", example: "Uma mudança tributária elevar custos ou uma disputa impedir o recebimento previsto.", caution: "Riscos legais e regulatórios são relacionados, mas podem ter classificações diferentes conforme a análise." },
  { id: "risco-vacancia", name: "Risco de vacância", description: "Risco de um imóvel ficar sem ocupação e deixar de gerar o aluguel esperado. Afeta proprietários e fundos que dependem dessas receitas.", example: "Um inquilino sair de um galpão e o imóvel ficar meses sem um novo contrato." },
  { id: "curto-prazo", name: "Curto prazo", description: "Horizonte próximo para usar o dinheiro ou concluir uma meta. No planejamento pessoal, costuma envolver meses ou poucos anos, conforme o contexto.", caution: "Não há uma divisão universal entre prazos. Defina a data e considere quanto tempo pode esperar para sacar." },
  { id: "medio-prazo", name: "Médio prazo", description: "Horizonte intermediário entre necessidades próximas e planos distantes. Pode envolver alguns anos, dependendo do objetivo.", example: "Planejar a entrada de um imóvel para daqui a três anos.", caution: "A duração varia conforme o contexto. Use uma data concreta, não apenas o rótulo médio prazo." },
  { id: "longo-prazo", name: "Longo prazo", description: "Horizonte de vários anos para alcançar um objetivo, como aposentadoria. Permite planejar etapas, mas exige revisar o plano conforme a vida muda.", caution: "Esperar mais tempo não garante lucro nem elimina riscos. O prazo deve combinar com a necessidade do dinheiro." },
  { id: "juro-nominal", name: "Juro nominal", aliases: ["Juros nominais", "Juros nominal", "Taxa nominal", "Rentabilidade nominal"], description: "Ganho expresso em dinheiro ou percentual antes de ajustar pela inflação. Mostra quanto o saldo mudou, não quanto aumentou seu poder de compra.", formula: "Retorno nominal sem novos depósitos ou retiradas = (valor final − valor inicial) ÷ valor inicial × 100", example: "R$ 1.000 que viram R$ 2.853,12 representam ganho nominal de 185,31% no período: (2.853,12 − 1.000) ÷ 1.000 × 100.", caution: "Essa conta considera que os ganhos estão no saldo final e não houve depósitos ou retiradas. Não é uma taxa anual se o período for diferente de um ano." },
  { id: "iptu", name: "IPTU", aliases: ["Imposto sobre a Propriedade Predial e Territorial Urbana"], description: "Imposto municipal sobre a propriedade de imóveis urbanos, como casas, apartamentos e terrenos. O cálculo e as condições de pagamento seguem as regras do município.", caution: "Em aluguel, confira a responsabilidade pelo pagamento no contrato. Isenções e descontos variam por município." },
  { id: "itbi", name: "ITBI", aliases: ["Imposto sobre a Transmissão de Bens Imóveis"], description: "Imposto municipal sobre certas transferências de imóveis entre pessoas, como uma compra e venda. É um custo a considerar além do preço do imóvel.", caution: "Confira a base de cálculo, a alíquota e o momento de pagamento no município. Doações e heranças seguem regras de outro imposto." },
  { id: "minha-casa-minha-vida", name: "Minha Casa, Minha Vida", aliases: ["MCMV"], description: "Programa habitacional federal que apoia o acesso à moradia. Pode oferecer subsídios, que ajudam a pagar parte do imóvel, e condições de financiamento conforme a modalidade.", caution: "Renda, imóvel e demais requisitos determinam o acesso. Consulte as regras atuais; o benefício não é automático." },
  { id: "caucao", name: "Caução", aliases: ["Caução de aluguel"], description: "Garantia entregue para cobrir obrigações de um contrato. No aluguel de imóvel urbano, a caução em dinheiro pode ser de até três meses de aluguel e deve ser depositada em poupança.", example: "Para aluguel de R$ 1.000, a caução em dinheiro pode chegar a R$ 3.000.", caution: "A devolução considera obrigações pendentes e os rendimentos da poupança. Não é pagamento dos últimos aluguéis, salvo acordo aplicável." },
  { id: "receita-federal", name: "Receita Federal", aliases: ["RF", "Leão"], description: "Órgão federal que administra tributos da União, como o Imposto de Renda, e atua no controle aduaneiro, ligado à entrada e saída de mercadorias do país.", caution: "Não administra todos os impostos: IPTU e ITBI, por exemplo, são municipais." },
  { id: "imposto-renda", name: "Imposto de Renda", aliases: ["IR", "IRPF", "IRPJ"], description: "Tributo sobre rendimentos, lucros e ganhos, conforme as regras de cada situação. Pode atingir salários, investimentos e ganhos na venda de bens.", caution: "Declarar não significa necessariamente pagar imposto. Alíquotas, isenções, prazos e forma de recolhimento variam." },
  { id: "sac", name: "SAC", aliases: ["Sistema de Amortização Constante"], description: "Forma de pagar uma dívida em que a parte que devolve o dinheiro emprestado é constante. Com juros fixos sobre o saldo que falta pagar, as parcelas diminuem ao longo do tempo.", example: "R$ 12.000 divididos em 12 amortizações de R$ 1.000. A 1% ao mês, a primeira parcela é R$ 1.120 e a segunda R$ 1.110, sem outros custos.", caution: "Correção monetária, seguros e tarifas podem alterar o valor cobrado." },
  { id: "price", name: "Price", aliases: ["Tabela Price", "Sistema Francês de Amortização"], description: "Forma de pagar uma dívida com parcelas iguais quando a taxa é fixa e não há outros ajustes. No início, uma parte maior paga juros; depois, aumenta a parte que reduz a dívida.", caution: "Índices de correção, seguros e tarifas podem mudar as parcelas cobradas. Compare o CET e o custo total, não apenas a parcela inicial." },
  { id: "consorcio", name: "Consórcio", description: "Grupo que contribui para formar recursos destinados à compra de bens ou serviços. O direito de usar o crédito ocorre por contemplação, por sorteio ou lance, conforme as regras.", caution: "Não garante receber o crédito logo. Há taxa de administração e possíveis outros custos e reajustes, mesmo sem juros de financiamento." },
  { id: "valor-presente", name: "Valor presente", aliases: ["PV", "VP", "Valor atual"], description: "Quanto um valor futuro equivale hoje considerando uma taxa de desconto, que representa o retorno exigido para esperar. Ajuda a comparar valores recebidos em datas diferentes.", formula: "Valor presente = valor futuro ÷ (1 + taxa do período)^número de períodos", example: "R$ 1.100 recebidos daqui a um ano equivalem a R$ 1.000 hoje com desconto de 10% ao ano: 1.100 ÷ 1,10.", caution: "Use a taxa em decimal e o prazo na mesma unidade. O valor calculado depende da taxa escolhida." },
  { id: "valor-futuro", name: "Valor futuro", aliases: ["FV", "VF"], description: "Quanto um valor atual pode alcançar em uma data futura, considerando uma taxa de crescimento e um prazo. É uma projeção, não necessariamente um ganho garantido.", formula: "Valor futuro = valor presente × (1 + taxa do período)^número de períodos", example: "R$ 1.000 a 10% ao ano por dois anos viram R$ 1.210: 1.000 × 1,10², sem novos depósitos ou custos.", caution: "Use a taxa em decimal e o prazo na mesma unidade. Taxas variáveis, impostos e retiradas mudam o resultado." },
  { id: "fluxo-caixa", name: "Fluxo de caixa", description: "Sequência de entradas e saídas de dinheiro com suas respectivas datas. Permite acompanhar pagamentos e recebimentos ou analisar um investimento.", example: "Pagar R$ 1.000 hoje é uma saída; receber R$ 600 em cada um dos próximos dois anos são entradas.", caution: "Lucro contábil não é necessariamente dinheiro recebido no mesmo momento." },
  { id: "custo-oportunidade", name: "Custo de oportunidade", description: "Benefício da melhor alternativa que você deixa de escolher ao usar dinheiro, tempo ou recursos em outra opção.", example: "Ao usar dinheiro em um projeto, você abre mão do retorno que poderia obter em outro investimento adequado.", caution: "Compare alternativas com prazos e riscos compatíveis, não apenas o maior rendimento anunciado." },
  { id: "tma", name: "TMA", aliases: ["Taxa Mínima de Atratividade"], description: "Retorno mínimo exigido para considerar um investimento. Leva em conta alternativas disponíveis, risco e prazo; pode usar Selic ou CDI como referências.", caution: "Não há uma TMA igual para todos. Um índice de inflação, como IGP-M, sozinho pode não compensar riscos ou representar a melhor alternativa." },
  { id: "tir", name: "TIR", aliases: ["Taxa Interna de Retorno"], description: "Taxa de desconto que faz o VPL de entradas e saídas de um investimento ser zero. Resume o retorno dos fluxos previstos para comparação com a taxa mínima exigida, a TMA.", example: "Pagar R$ 1.000 hoje e receber R$ 1.100 em um ano produz TIR de 10% ao ano. Se a TMA for 8%, o retorno previsto supera o mínimo exigido.", caution: "TIR abaixo da TMA não significa necessariamente prejuízo: pode indicar apenas retorno insuficiente para o critério. Alguns fluxos têm várias TIRs ou nenhuma; avalie também o VPL e os riscos." },
  { id: "vpl", name: "VPL", aliases: ["Valor Presente Líquido"], description: "Soma das entradas e saídas previstas, trazidas para a data de hoje pela taxa de desconto escolhida. Um VPL positivo indica valor acima do retorno exigido; negativo indica que esse critério não foi atendido.", formula: "VPL = soma de [fluxo do período ÷ (1 + taxa de desconto)^número do período], usando entradas positivas e saídas negativas", example: "Pagar R$ 1.000 hoje e receber R$ 1.100 em um ano, com desconto de 10%, dá VPL zero: −1.000 + 1.100 ÷ 1,10 = 0.", caution: "Inclua o pagamento inicial no período zero. O resultado depende das projeções e da taxa escolhida; não garante viabilidade. Use taxa em decimal e períodos na mesma unidade, ou um cálculo que considere as datas exatas." },
  { id: "b3", name: "B3", aliases: ["Brasil, Bolsa, Balcão", "Brasil Bolsa e Balcão", "Bovespa", "BM&FBovespa"], description: "Empresa que opera a bolsa brasileira e estruturas de registro, negociação, liquidação e guarda de ativos. Seu nome é Brasil, Bolsa, Balcão; reúne atividades da antiga BM&FBovespa e da Cetip.", caution: "A B3 organiza o mercado, mas não garante que um investimento dará lucro." },
  { id: "corretora-valores", name: "Corretora de valores", aliases: ["Corretoras de valores", "Corretora"], description: "Instituição que intermedeia investimentos e envia ordens de compra e venda aos mercados. Pode oferecer uma plataforma para negociar e acompanhar sua carteira.", example: "BTG Pactual, XP e Rico.", caution: "Confira autorização, taxas e serviços. Uma oferta pela corretora não significa que ela garante o retorno do produto." },
  { id: "investidor", name: "Investidor", aliases: ["Investidores"], description: "Pessoa ou empresa que aplica recursos buscando um resultado futuro. Pode investir em ações, renda fixa, fundos e outros ativos, não apenas na bolsa.", caution: "Objetivos, prazo e capacidade de assumir perdas devem orientar a escolha." },
  { id: "investidor-qualificado", name: "Investidor qualificado", description: "Categoria da CVM que permite acesso a certos produtos. Uma das formas de enquadramento exige mais de R$ 1 milhão em investimentos financeiros e declaração escrita de que a pessoa ou empresa é qualificada.", caution: "Há outras formas previstas na norma. Ter patrimônio elevado não elimina riscos, e nem todo produto exige essa classificação." },
  { id: "mercado-primario", name: "Mercado primário", description: "Mercado em que novos títulos ou ações são emitidos e vendidos aos investidores. Os recursos vão para quem emite, como a empresa que busca dinheiro para seus projetos.", caution: "Não se limita ao IPO. Uma empresa já listada também pode emitir novas ações, e um IPO pode incluir ações já existentes." },
  { id: "mercado-secundario", name: "Mercado secundário", description: "Mercado em que investidores negociam ativos já emitidos. O dinheiro da venda vai para o vendedor, não para a empresa que emitiu originalmente.", example: "Comprar ações BBAS3 de outro investidor em bolsa." },
  { id: "ipo", name: "IPO", aliases: ["Initial Public Offering", "Oferta Pública Inicial"], description: "Primeira oferta pública de ações de uma empresa. Pode incluir novas ações, com dinheiro para a empresa, e ações de sócios, com dinheiro para os vendedores.", caution: "Ser uma estreia em bolsa não garante valorização ou preço vantajoso." },
  { id: "mercado-balcao", name: "Mercado de balcão", aliases: ["Balcão organizado", "Balcão não organizado"], description: "Ambiente de negociação de ativos fora do mercado de bolsa. Pode ser organizado, com regras e supervisão próprias, ou envolver negociações diretas entre as partes.", caution: "Não é necessariamente sem regulação nem exclusivo de investidores qualificados. Liquidez, transparência e acesso dependem do ativo e do ambiente." },
  { id: "d-mais", name: "D+", aliases: ["D+0", "D+1", "D+2", "D+15", "Prazo D+"], description: "Notação de prazo: D é a data de referência e o número indica quantos dias depois ocorre uma etapa, como pagamento ou resgate.", example: "D+0: no mesmo dia; D+1: um dia depois; D+2: dois dias depois; D+15: quinze dias depois.", caution: "Confira se são dias úteis ou corridos, o horário limite e a etapa contada. Em fundos, o prazo para calcular a cota pode ser diferente do prazo para receber o dinheiro." },
  { id: "liquidez-diaria", name: "Liquidez diária", description: "Possibilidade de pedir a retirada do investimento em cada dia permitido pelas regras do produto, normalmente dias úteis. Não significa necessariamente receber no mesmo dia.", caution: "Confira o prazo de pagamento e os horários. D+0 indica uma etapa no mesmo dia, não disponibilidade garantida a qualquer hora." },
  { id: "iof", name: "IOF", aliases: ["Imposto sobre Operações Financeiras"], description: "Imposto que pode incidir em operações como crédito, câmbio e determinados investimentos. Em aplicações sujeitas à tabela regressiva, resgates antes de 30 dias podem ter cobrança sobre os rendimentos.", example: "Na tabela regressiva dessas aplicações, o IOF diminui com o prazo e chega a zero no 30º dia.", caution: "Essa regra não vale para todo IOF ou investimento. Outras operações têm bases de cálculo e regras diferentes; confira a tributação do produto." },
  { id: "ir-regressivo", name: "Tabela regressiva de IR", aliases: ["IR regressivo", "Imposto de Renda regressivo"], description: "Tabela usada em aplicações de renda fixa tributáveis, como CDBs e títulos do Tesouro. A alíquota sobre os rendimentos diminui conforme o tempo aplicado.", example: "Até 180 dias: 22,5%; de 181 a 360: 20%; de 361 a 720: 17,5%; a partir de 721 dias: 15%. Os prazos são em dias corridos.", caution: "Não é a regra de todos os investimentos nem a tabela de salários. Fundos podem ter regras próprias, e há produtos com isenção. Confirme a legislação vigente." },
  { id: "taxa-prefixada", name: "Taxa prefixada", aliases: ["Prefixada", "Prefixado"], description: "Taxa definida na contratação. Permite calcular os pagamentos previstos se o investimento ou dívida seguir as condições combinadas até o fim.", caution: "Não acompanha automaticamente a inflação. O risco depende do produto e de quem paga; na venda antecipada, o preço pode mudar e causar perdas." },
  { id: "taxa-pos-fixada", name: "Taxa pós-fixada", aliases: ["Pós-fixada", "Pós-fixado"], description: "Taxa cujo resultado acompanha uma referência que varia, como CDI ou Selic. A regra é conhecida no início, mas o ganho total depende do comportamento da referência.", example: "Um CDB que rende 100% do CDI.", caution: "Pós-fixado não significa baixo risco nem proteção automática contra inflação. CDI e Selic não são índices de preços." },
  { id: "taxa-hibrida", name: "Taxa híbrida", aliases: ["Híbrida", "Indexada", "Taxa indexada"], description: "Regra que combina uma referência variável com uma taxa fixa. Nos investimentos ligados ao IPCA, por exemplo, o resultado combina inflação e juros contratados.", example: "IPCA + 5% ao ano, antes de custos e impostos.", caution: "As taxas são combinadas conforme o contrato, não necessariamente por soma simples. Indexada também pode designar outras regras ligadas a índices; não é sinônimo obrigatório de híbrida." },
  { id: "commodities", name: "Commodities", aliases: ["Commodity"], description: "Produtos básicos negociados com características padronizadas, como petróleo, minério de ferro, soja e ouro. Seus preços dependem de oferta, demanda e condições globais.", caution: "Investir em uma empresa produtora não é o mesmo que comprar diretamente a commodity." },
  { id: "cotacao", name: "Cotação", description: "Preço de um ativo informado em determinado momento. Pode ser o último negócio ou uma oferta de compra ou venda, conforme a tela consultada.", example: "BBAS3 a R$ 30,00 por ação, em um exemplo fictício.", caution: "O preço exibido não garante que sua ordem será executada por esse valor. Mercados padrão e fracionário podem ter ofertas diferentes." },
  { id: "lote-padrao", name: "Lote padrão", aliases: ["Lotes", "Mercado padrão"], description: "Quantidade mínima por lote definida para a negociação de um ativo. Muitas ações na B3 usam lotes de 100, mas há ativos com outros tamanhos.", example: "100 ações a R$ 30,00 custam R$ 3.000, antes de taxas.", caution: "Confira o lote do ativo. Uma ordem pode negociar vários lotes, e o ticker sozinho não informa quantas ações você comprou." },
  { id: "mercado-fracionario", name: "Mercado fracionário", aliases: ["Lote fracionário", "Fracionado"], description: "Permite negociar uma quantidade de ações menor que o lote padrão. Para ações com lote de 100, são de 1 a 99 por ordem; o código costuma receber F ao final.", example: "BBAS3F: 10 ações a R$ 30,50 custam R$ 305, antes de taxas. O preço é fictício.", caution: "São ações do mesmo tipo, não frações de uma ação. As ofertas podem diferir das do mercado padrão." },
  { id: "prazo-liquidacao", name: "Prazo de liquidação", aliases: ["Liquidação", "Data de liquidação"], description: "Tempo entre a negociação e a conclusão do pagamento e da transferência do ativo. Para ações à vista na B3, a regra atual é D+2, dois dias úteis após o negócio.", example: "Compra na segunda-feira liquida na quarta-feira se não houver feriado.", caution: "A posição pode aparecer antes na plataforma. Negociar novamente antes da liquidação não dispensa as obrigações de pagamento; confira regras e saldo com a corretora." },
  { id: "ordem-limitada", name: "Ordem limitada", aliases: ["Ordem limite"], description: "Ordem que define o máximo que você aceita pagar na compra ou o mínimo que aceita receber na venda. Pode executar por esse preço ou por um preço mais favorável.", example: "Compra limitada a R$ 30 pode executar a R$ 29. Venda limitada a R$ 30 pode executar a R$ 31.", caution: "O preço ser atingido não garante execução. É preciso haver contraparte e quantidade disponível, respeitando a fila; pode executar só uma parte." },
  { id: "ordem-mercado", name: "Ordem a mercado", description: "Ordem para negociar com as ofertas disponíveis, sem definir um preço limite. Prioriza a execução, mas o preço pode mudar entre o envio e o negócio.", caution: "Pode executar em vários preços ou só parcialmente. Não garante o último preço exibido, especialmente em ativos pouco negociados." },
  { id: "ordem-agendada", name: "Ordem agendada", aliases: ["Agendamento de ordem"], description: "Ordem preparada para ser enviada em outro momento, como na abertura do mercado ou em uma data escolhida, se a plataforma permitir.", caution: "Agendar não garante execução. Confira quando será enviada, sua validade e as regras da corretora." },
  { id: "ordem-stop", name: "Ordem stop", aliases: ["Stop", "Preço de disparo", "Stop loss", "Stop gain"], description: "Ordem acionada quando o preço atinge uma condição de disparo. Após o disparo, pode virar uma ordem limitada ou a mercado, conforme o tipo oferecido pela plataforma.", example: "Em um stop de venda, disparo a R$ 50 e limite a R$ 49,50 permitem vender por R$ 49,50 ou mais, se houver comprador.", caution: "O disparo não garante execução. Se o preço cair direto abaixo do limite, a ordem limitada pode não vender; a ordem a mercado não garante preço." },
  { id: "stop-movel", name: "Stop móvel", aliases: ["Ordem stop móvel", "Trailing stop"], description: "Stop cujo disparo acompanha movimentos favoráveis do preço. Em uma venda, pode subir quando o ativo sobe, mantendo a distância configurada.", caution: "Disponibilidade e regras variam por plataforma. Não garante lucro nem execução no valor de disparo." },
  { id: "ordem-oco", name: "Ordem OCO", aliases: ["OCO", "One Cancels the Other", "Uma cancela a outra"], description: "Liga duas ordens para que a execução de uma cancele a outra, conforme as regras da plataforma. Costuma combinar uma saída no ganho e outra para limitar perdas.", example: "Após comprar a R$ 10, configurar uma saída a R$ 11 e outra por stop a R$ 9,50.", caution: "Não garante o preço de saída. Confira como a plataforma trata execuções parciais, ajustes de quantidade e cancelamentos." },
  { id: "validade-ordem", name: "Validade da ordem", aliases: ["Validade das ordens"], description: "Define até quando uma ordem pode permanecer ativa ou como deve executar. É diferente do preço limite e da condição de disparo.", caution: "Opções e nomes variam por mercado e plataforma. Confira a validade antes de enviar." },
  { id: "ordem-dia", name: "Ordem válida para o dia", aliases: ["Dia", "DAY"], description: "Ordem que permanece válida apenas na sessão de negociação daquele dia. Ao fim da validade, a quantidade que não foi executada é cancelada.", caution: "O cancelamento do restante não desfaz negócios já executados." },
  { id: "ordem-datada", name: "Ordem válida até uma data", aliases: ["Ordem datada", "GTD"], description: "Ordem que pode permanecer ativa até a data escolhida, conforme as regras do mercado e da corretora. O saldo não executado é cancelado quando a validade termina.", caution: "Pode ser cancelada antes por regras da plataforma ou eventos do ativo." },
  { id: "ordem-vac", name: "Ordem válida até cancelar", aliases: ["VAC", "GTC"], description: "Ordem que permanece ativa até ser executada ou cancelada, dentro das regras do mercado e da plataforma.", caution: "Não significa duração ilimitada garantida. Eventos do ativo, limites de validade e regras da corretora podem cancelar ou ajustar a ordem." },
  { id: "ordem-eoc", name: "Executa ou cancela", aliases: ["EOC", "IOC", "FAK", "Immediate or Cancel"], description: "Instrução para executar imediatamente a quantidade disponível e cancelar o restante. Pode permitir execução parcial, sem deixar saldo ativo aguardando novas ofertas.", example: "Ordem de 100 ações com 50 disponíveis no preço aceito: executa 50 e cancela as outras 50.", caution: "Confira a definição na plataforma. Não confunda com execução completa e imediata, chamada Fill or Kill (FOK)." },
  { id: "ordem-fok", name: "Fill or Kill", aliases: ["FOK", "Tudo ou nada imediato"], description: "Instrução que exige executar toda a quantidade imediatamente. Se não houver quantidade suficiente nas condições aceitas, a ordem inteira é cancelada.", example: "Ordem de 100 ações com apenas 50 disponíveis: não executa nenhuma e é cancelada.", caution: "Não espera até o fim do dia para completar a quantidade. Nomes como tudo ou nada podem ter regras diferentes nas plataformas; confira a instrução." },
  { id: "fundo-aberto", name: "Fundo aberto", aliases: ["Fundos abertos", "Classe aberta"], description: "Fundo ou classe que permite solicitar resgate de cotas conforme as regras do regulamento. Aplicações e retiradas seguem prazos e condições definidos.", caution: "Aberto não significa saque imediato ou sem restrições. Confira carência, cálculo da cota e prazo de pagamento; pode haver suspensão de resgates em situações excepcionais." },
  { id: "fundo-fechado", name: "Fundo fechado", aliases: ["Fundos fechados", "Classe fechada"], description: "Fundo ou classe que não permite resgatar cotas durante seu funcionamento. Pode devolver recursos por amortizações previstas ou no encerramento. Quando há negociação, o investidor pode vender suas cotas a outra pessoa.", caution: "Pode haver novas emissões de cotas. Nem todo fundo fechado é negociado em bolsa, e vender não garante recuperar o valor aplicado." },
  { id: "fundo-passivo", name: "Fundo passivo", aliases: ["Fundos passivos", "Fundo indexado", "Fundos indexados"], description: "Fundo que busca acompanhar uma referência, como CDI, Ibovespa ou outro índice. A gestão procura manter o resultado próximo da referência, em vez de superá-la.", caution: "Taxas, custos e diferenças na carteira impedem uma reprodução necessariamente exata. Gestão passiva não significa ausência de risco." },
  { id: "fundo-ativo", name: "Fundo ativo", aliases: ["Fundos ativos", "Gestão ativa"], description: "Fundo cujo gestor escolhe posições buscando superar uma referência ou atingir outro objetivo da estratégia. Pode mudar a carteira conforme sua análise.", caution: "Não precisa assumir sempre mais risco que a referência. Pode ficar abaixo dela; confira estratégia, custos e limites do regulamento." },
  { id: "perfil-risco", name: "Perfil de risco", aliases: ["Perfil do investidor", "Suitability"], description: "Avaliação que considera objetivos, prazo, conhecimento e capacidade de suportar perdas para verificar quais investimentos são adequados ao investidor.", example: "Conservador, moderado e arrojado são classificações comuns.", caution: "Os critérios variam entre instituições e podem mudar com sua situação. O perfil não garante retorno." },
  { id: "perfil-conservador", name: "Perfil conservador", aliases: ["Conservador"], description: "Perfil que prioriza preservar recursos e aceita pouca oscilação ou possibilidade de perda. Costuma valorizar previsibilidade e acesso ao dinheiro.", caution: "Conservador não significa risco zero. Confira riscos de pagamento, inflação e prazo de resgate." },
  { id: "perfil-moderado", name: "Perfil moderado", aliases: ["Moderado"], description: "Perfil que aceita alguma oscilação e possibilidade de perda para buscar ganhos maiores, equilibrando proteção e crescimento.", caution: "Não existe uma proporção universal de renda fixa e variável. A escolha depende de objetivos e prazos." },
  { id: "perfil-arrojado", name: "Perfil arrojado", aliases: ["Arrojado", "Agressivo"], description: "Perfil que aceita oscilações maiores e risco de perdas buscando retorno mais alto. Precisa ter capacidade financeira e disposição para lidar com esses resultados.", caution: "Aceitar risco não garante ganhos maiores nem justifica investir dinheiro necessário no curto prazo." },
  { id: "previdencia-privada", name: "Previdência privada", aliases: ["Previdência complementar"], description: "Plano para acumular recursos e complementar a renda futura. Pode oferecer resgate ou formas de recebimento conforme o contrato, sem substituir automaticamente a previdência pública.", caution: "Confira taxas, investimentos, tributação e condições de renda. PGBL e VGBL não têm retorno mínimo garantido na acumulação nem garantia do FGC." },
  { id: "vgbl", name: "VGBL", aliases: ["Vida Gerador de Benefícios Livres"], description: "Seguro de pessoas com cobertura por sobrevivência, usado para acumular recursos. O IR no resgate ou recebimento de renda incide sobre os rendimentos, não sobre todo o valor.", caution: "Aportes não são dedutíveis no IR. Pode ser avaliado por quem não aproveita a dedução do PGBL, mas custos, prazo e riscos também importam." },
  { id: "pgbl", name: "PGBL", aliases: ["Plano Gerador de Benefícios Livres"], description: "Plano de previdência complementar. Pode permitir deduzir contribuições de até 12% dos rendimentos tributáveis anuais na declaração com deduções legais, cumpridas as condições. No resgate ou benefício, o IR incide sobre o valor total.", example: "Com R$ 100.000 de rendimentos tributáveis no ano, o limite de dedução pode ser R$ 12.000. Isso reduz a base de cálculo, não o imposto diretamente em R$ 12.000.", caution: "A dedução exige requisitos, como contribuição à previdência oficial nos casos aplicáveis. É adiamento da tributação, não isenção; não se aplica a toda receita bruta." },
  { id: "tributacao-progressiva-previdencia", name: "Tributação progressiva da previdência", aliases: ["Tabela progressiva", "Regime progressivo"], description: "Regime em que a parcela tributável recebida do plano entra no cálculo do IR conforme as regras progressivas. A alíquota final depende da renda e das deduções no período.", caution: "Resgates geralmente têm retenção de 15% como antecipação, com ajuste na declaração anual. Benefícios seguem regras de retenção próprias. Consulte a tabela vigente; não há escolha melhor para todos." },
  { id: "tributacao-regressiva-previdencia", name: "Tributação regressiva da previdência", aliases: ["Tabela regressiva da previdência", "Regime regressivo"], description: "Regime em que o IR diminui com o tempo de acumulação. Nos resgates, o prazo de cada aporte importa; a tributação é definitiva, sem ajuste pela tabela progressiva anual.", example: "Até 2 anos: 35%; acima de 2 até 4: 30%; acima de 4 até 6: 25%; acima de 6 até 8: 20%; acima de 8 até 10: 15%; acima de 10 anos: 10%.", caution: "Não é a tabela regressiva de CDBs. Benefícios podem usar regras próprias de prazo; a base tributável é diferente no PGBL e no VGBL." },
  { id: "portabilidade-previdencia", name: "Portabilidade da previdência", aliases: ["Portabilidade de planos"], description: "Transferência de recursos entre planos compatíveis sem resgatar o dinheiro para sua conta. Permite mudar de plano ou instituição conforme as regras aplicáveis.", caution: "PGBL não pode ser convertido em VGBL, nem o contrário. Confira carências, preservação dos prazos tributários e condições; portabilidade não é resgate." },
  { id: "sucessao-patrimonial", name: "Sucessão patrimonial", description: "Planejamento de como bens e direitos serão transmitidos após a morte. Pode envolver beneficiários, herdeiros, documentos e diferentes instrumentos.", caution: "Previdência e seguros podem participar do plano, mas não são soluções universais. Regras civis, tributárias e do contrato exigem análise específica." },
  { id: "come-cotas", name: "Come-cotas", description: "Cobrança periódica de IR sobre rendimentos de fundos sujeitos a essa regra. O imposto é recolhido reduzindo a quantidade de cotas do investidor, normalmente no último dia útil de maio e novembro.", example: "Na regra geral, fundos tributários de longo prazo usam 15% e os de curto prazo 20%, com possível complemento no resgate.", caution: "Não vale para todos os fundos. PGBL e VGBL não sofrem esse come-cotas; há exceções para outras categorias e condições específicas." },
  { id: "fii-hibrido", name: "FII híbrido", aliases: ["Fundos híbridos", "Fundo imobiliário híbrido"], description: "Fundo imobiliário que combina estratégias, como imóveis físicos e títulos do setor. A distribuição entre elas segue o regulamento e as decisões da gestão.", caution: "Não há obrigação geral de dividir 50% em tijolo e 50% em papel. Confira a carteira real do fundo." },
  { id: "fii-hedge-fund", name: "FII hedge fund", aliases: ["Hedge fund imobiliário", "FII multiestratégia"], description: "Nome de mercado para FIIs com estratégias amplas, combinando imóveis, títulos, cotas de fundos e outros investimentos permitidos pelo regulamento.", caution: "Não é sinônimo de todo hedge fund ou fundo multimercado. A liberdade de investir depende das regras do FII." },
  { id: "hedge-fund", name: "Hedge fund", aliases: ["Hedge funds"], description: "Nome usado para fundos com estratégias flexíveis, que podem buscar resultados em diferentes cenários, inclusive com posições de proteção ou apostas de queda.", caution: "Não é uma categoria legal única no Brasil nem sinônimo exato de multimercado. Pode envolver riscos elevados e restrições de acesso." },
  { id: "fundo-multimercado", name: "Fundo multimercado", aliases: ["Multimercado", "Fundos multimercado"], description: "Fundo que pode combinar diferentes fatores de risco, como juros, ações e câmbio, sem concentrar sua estratégia obrigatoriamente em apenas um deles.", caution: "Multimercado não significa diversificação garantida ou risco baixo. Confira os investimentos e os limites da estratégia." },
  { id: "fundo-fundos", name: "Fundo de fundos", aliases: ["FOF", "Fundos de fundos"], description: "Fundo que aplica principalmente em cotas de outros fundos. No mercado imobiliário, um FOF reúne participações em diferentes FIIs.", caution: "Pode facilitar a diversificação, mas há custos nos dois níveis e possível repetição dos mesmos riscos na carteira." },
  { id: "empresa-ciclica", name: "Empresa cíclica", aliases: ["Empresas cíclicas"], description: "Empresa cujas receitas e resultados costumam variar bastante com os ciclos econômicos. A demanda pode crescer em períodos favoráveis e cair nas desacelerações.", example: "Empresas de bens duráveis e de commodities podem apresentar comportamento cíclico.", caution: "O efeito depende do negócio; juros, câmbio e oferta também influenciam os resultados." },
  { id: "empresa-nao-ciclica", name: "Empresa não cíclica", aliases: ["Empresas não cíclicas", "Empresa defensiva"], description: "Empresa cuja demanda tende a variar menos com a economia, por atender necessidades mais recorrentes ou essenciais.", example: "Negócios de alimentos básicos, saúde e saneamento podem ter demanda mais estável.", caution: "Não significa lucro estável ou proteção automática contra juros e inflação. Custos, dívidas e regulação também afetam esses negócios." },
  { id: "aswath-damodaran", name: "Aswath Damodaran", aliases: ["Damodaran", "Damodaram"], description: "Professor de finanças da NYU e referência em avaliação de empresas. Ensina métodos para estimar valor a partir de resultados futuros, risco e crescimento.", caution: "Estimativas de valor dependem de hipóteses e não garantem o preço futuro da ação." },
  { id: "benjamin-graham", name: "Benjamin Graham", aliases: ["Graham"], description: "Investidor e autor associado ao investimento em valor: analisar fundamentos e buscar uma margem entre o valor estimado e o preço pago.", caution: "A margem de segurança depende da qualidade da estimativa e não elimina perdas." },
  { id: "decio-bazin", name: "Décio Bazin", aliases: ["Bazin"], description: "Investidor e autor brasileiro conhecido por uma abordagem de seleção de ações com foco em dividendos e disciplina na avaliação do preço.", caution: "Dividendos passados ou altos não garantem pagamentos futuros nem uma boa compra." },
  { id: "myron-gordon", name: "Myron Gordon", aliases: ["Gordon"], description: "Economista associado ao modelo de crescimento de dividendos de Gordon. O modelo estima o valor de uma ação a partir de dividendos futuros com crescimento constante." },
  { id: "modelo-gordon", name: "Modelo de Gordon", aliases: ["Gordon-Shapiro", "Gordon Growth Model"], description: "Modelo que estima o valor de uma ação supondo que seus dividendos cresçam a uma taxa constante. Compara os pagamentos esperados com o retorno exigido pelo investidor.", formula: "Valor estimado = dividendo esperado do próximo período ÷ (taxa de retorno exigida − taxa de crescimento)", example: "Dividendo anual esperado de R$ 3, retorno exigido de 10% e crescimento de 4% resultam em R$ 50: 3 ÷ (0,10 − 0,04).", caution: "As taxas devem usar o mesmo período e formato decimal. O retorno exigido precisa superar o crescimento; pequenas mudanças nas hipóteses alteram muito o resultado." },
  { id: "luiz-barsi", name: "Luiz Barsi Filho", aliases: ["Barsi"], description: "Investidor brasileiro conhecido pelo foco de longo prazo em empresas que distribuem dividendos e pela formação de renda com ações.", caution: "Seguir uma pessoa ou sua carteira não garante resultados semelhantes." },
  { id: "peter-lynch", name: "Peter Lynch", aliases: ["Lynch"], description: "Investidor e ex-gestor do fundo Magellan, da Fidelity. É conhecido por estudar negócios compreensíveis e relacionar perspectivas de crescimento ao preço das ações.", caution: "Conhecer um produto não substitui analisar as finanças e o preço da empresa." },
  { id: "warren-buffett", name: "Warren Buffett", aliases: ["Buffett"], description: "Investidor associado à Berkshire Hathaway, conhecido por avaliar empresas, vantagens competitivas e preço com foco no longo prazo.", caution: "Seu histórico não garante ganhos ao copiar decisões ou estratégias." },
  { id: "george-soros", name: "George Soros", aliases: ["Soros"], description: "Investidor conhecido por estratégias ligadas a cenários econômicos e pela reflexividade: como expectativas dos participantes podem influenciar o próprio mercado.", caution: "Essas estratégias podem envolver posições complexas e perdas elevadas." },
  { id: "ray-dalio", name: "Ray Dalio", aliases: ["Dalio"], description: "Fundador da Bridgewater Associates, conhecido por estratégias macroeconômicas e pela combinação de investimentos com diferentes fontes de risco.", caution: "Diversificação e modelos de cenário não garantem proteção em todas as crises." },
  { id: "dre", name: "DRE", aliases: ["Demonstração do Resultado do Exercício"], description: "Relatório contábil que apresenta receitas, custos, despesas e impostos de um período, chegando ao lucro ou prejuízo da empresa.", caution: "Receita e lucro não significam necessariamente dinheiro recebido no período. Para entradas e saídas de dinheiro, veja a DFC." },
  { id: "dfc", name: "DFC", aliases: ["Demonstração dos Fluxos de Caixa", "Demonstração do Fluxo de Caixa"], description: "Relatório de entradas e saídas de dinheiro, dividido em operações do negócio, investimentos e financiamentos. Ajuda a entender de onde veio o caixa e como foi usado.", example: "Receber de clientes é operacional; comprar equipamentos é investimento; receber um empréstimo é financiamento.", caution: "Aumento do caixa não significa necessariamente lucro: pode vir de empréstimos ou venda de bens." },
];

export function normalizeGlossarySearch(value: string) {
  return value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim();
}

export const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("");

export function getGlossaryGroups(query: string) {
  const words = normalizeGlossarySearch(query).split(/\s+/).filter(Boolean);
  const terms = glossaryTerms.filter((term) => {
    const searchable = normalizeGlossarySearch([
      term.name, ...(term.aliases ?? []), term.description, term.formula ?? "",
      term.example ?? "", term.caution ?? "",
    ].join(" "));
    return words.every((word) => searchable.includes(word));
  }).sort((a, b) => a.name.localeCompare(b.name, "pt-BR"));
  return alphabet.map((letter) => ({
    letter,
    terms: terms.filter((term) => normalizeGlossarySearch(term.name).startsWith(letter.toLowerCase())),
  })).filter((group) => group.terms.length > 0);
}
